/**
 * 联机存档选项对话框
 *
 * 当用户尝试加载联机存档时弹出，提供以下选项：
 * - 开启新聚会：创建新房间，使用该存档数据
 * - 返回：取消操作
 */

import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogFooter } from "@/components/ui/dialog";
import type { SaveSlotInfo } from "@/core/yjs/types";
import { ArrowLeft, Loader2, Users } from "lucide-react";
import { useState } from "react";

interface MultiplayerSaveDialogProps {
  /** 是否打开 */
  open: boolean;
  /** 关闭回调 */
  onOpenChange: (open: boolean) => void;
  /** 存档信息 */
  save: SaveSlotInfo | null;
  /** 开启新聚会回调 */
  onStartNewParty: (save: SaveSlotInfo) => Promise<void>;
}

/**
 * 格式化时间
 */
function formatTime(timestamp: number): string {
  const date = new Date(timestamp);
  const now = new Date();
  const diff = now.getTime() - date.getTime();

  // 今天
  if (diff < 24 * 60 * 60 * 1000 && date.getDate() === now.getDate()) {
    return `今天 ${date.getHours().toString().padStart(2, "0")}:${date
      .getMinutes()
      .toString()
      .padStart(2, "0")}`;
  }

  // 昨天
  const yesterday = new Date(now);
  yesterday.setDate(yesterday.getDate() - 1);
  if (date.getDate() === yesterday.getDate()) {
    return `昨天 ${date.getHours().toString().padStart(2, "0")}:${date
      .getMinutes()
      .toString()
      .padStart(2, "0")}`;
  }

  // 更早
  return `${date.getMonth() + 1}/${date.getDate()} ${date
    .getHours()
    .toString()
    .padStart(2, "0")}:${date.getMinutes().toString().padStart(2, "0")}`;
}

export function MultiplayerSaveDialog({
  open,
  onOpenChange,
  save,
  onStartNewParty,
}: MultiplayerSaveDialogProps) {
  const [isStarting, setIsStarting] = useState(false);

  if (!save) return null;

  const handleStartNewParty = async () => {
    setIsStarting(true);
    try {
      await onStartNewParty(save);
      onOpenChange(false);
    } catch (_error) {
      // Silently handle error
    } finally {
      setIsStarting(false);
    }
  };

  const handleClose = () => {
    if (!isStarting) {
      onOpenChange(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent
        title="联机存档"
        description="这是一个联机存档，需要创建新房间才能继续游戏"
        className="max-w-md"
      >
        {/* 存档信息 */}
        <div className="space-y-4">
          {/* 存档名称和时间 */}
          <div className="p-4 rounded-lg bg-muted/30 border border-muted">
            <div className="flex items-center gap-3 mb-2">
              <div className="w-10 h-10 rounded-full bg-primary/20 flex items-center justify-center">
                <Users size={20} className="text-primary" />
              </div>
              <div>
                <h3 className="font-medium">{save.name}</h3>
                <p className="text-sm text-muted-foreground">
                  上次游戏：{formatTime(save.updatedAt)}
                </p>
              </div>
            </div>

            {/* 成员列表 */}
            {save.members && save.members.length > 0 && (
              <div className="mt-3 pt-3 border-t border-muted">
                <p className="text-sm text-muted-foreground mb-2">
                  上次成员 ({save.members.length}人)
                </p>
                <div className="flex flex-wrap gap-2">
                  {save.members.map((member, index) => (
                    <span
                      key={index}
                      className="text-xs px-2 py-1 rounded-full bg-muted/50"
                    >
                      {member.displayName}
                      {member.role === "host" && " 👑"}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* 说明文字 */}
          <p className="text-sm text-muted-foreground">
            联机存档需要创建新房间才能继续。创建后，你可以将新的房间码分享给其他玩家。
          </p>
        </div>

        {/* 操作按钮 */}
        <DialogFooter className="mt-6">
          <Button variant="ghost" onClick={handleClose} disabled={isStarting}>
            <ArrowLeft size={16} className="mr-2" />
            返回
          </Button>
          <Button onClick={handleStartNewParty} disabled={isStarting}>
            {isStarting ? (
              <>
                <Loader2 size={16} className="mr-2 animate-spin" />
                创建中...
              </>
            ) : (
              <>
                <Users size={16} className="mr-2" />
                开启新聚会
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * SaveManagerDialog - 存档管理弹窗
 *
 * 管理存档槽位（Save Slots），而非会话（Conversations）
 * 每个存档槽位是一个独立的游戏档案，包含多个会话
 *
 * 数据来源：
 * - 存档列表：useSaveSlots hook (订阅 Yjs)
 * - 当前存档 ID：useCurrentSaveId hook
 */

import { Button } from "@/components/ui/button";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import type { SaveSlotInfo } from "@/core/yjs/types";
import { DataCommands } from "@/domain/commands/data";
import { SaveCommands } from "@/domain/commands/save";
import { useCommand, useToast } from "@/hooks";
import { cn } from "@/lib/utils";
import { useCurrentSaveId, useSaveSlots } from "@/modules/save";
import {
  animation,
  borders,
  color,
  colorAlpha,
  glow,
  gradients,
} from "@/styles/tokens";
import { AnimatePresence, motion } from "framer-motion";
import {
  Clock,
  Download,
  FolderOpen,
  Gamepad2,
  Play,
  Plus,
  Trash2,
  Users,
} from "lucide-react";
import { useCallback, useMemo } from "react";

interface SaveManagerDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onLoadSave?: (saveId: string) => void;
  /** 联机存档加载回调 - 弹出选择对话框 */
  onMultiplayerSave?: (save: SaveSlotInfo) => void;
}

/**
 * 格式化相对时间
 */
function formatRelativeTime(timestamp: number): string {
  const now = Date.now();
  const diff = now - timestamp;

  const seconds = Math.floor(diff / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);

  if (days > 0) return days === 1 ? "昨天" : `${days}天前`;
  if (hours > 0) return `${hours}小时前`;
  if (minutes > 0) return `${minutes}分钟前`;
  return "刚刚";
}

/**
 * 单个存档卡片
 */
interface SaveCardProps {
  save: SaveSlotInfo;
  isActive: boolean;
  onLoad: () => void;
  onDelete: () => void;
  onExport: () => void;
  index: number;
}

function SaveCard({
  save,
  isActive,
  onLoad,
  onDelete,
  onExport,
  index,
}: SaveCardProps) {
  // 使用 Token 系统计算样式
  const cardStyles = useMemo(() => {
    return {
      active: {
        borderColor: color("primaryLight"),
        background: colorAlpha("primary", 0.1),
        boxShadow: glow("primary", "md", 0.3),
      },
      inactive: {
        borderColor: colorAlpha("primary", 0.2),
        background: colorAlpha("primary", 0.05),
      },
    };
  }, []);

  const indicatorStyles = useMemo(() => {
    return {
      background: gradients.primary(),
      boxShadow: glow("primary", "sm", 0.8),
    };
  }, []);

  return (
    <motion.div
      initial={{ opacity: 0, x: -20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: 20 }}
      transition={{ delay: index * 0.05, duration: animation.duration.normal }}
      className={cn(
        "relative group p-4 border-2",
        `transition-all duration-[${animation.duration.normal * 1000}ms]`
      )}
      style={{
        borderRadius: borders.radius.lg,
        ...(isActive ? cardStyles.active : cardStyles.inactive),
      }}
    >
      {/* 活跃指示器 */}
      {isActive && (
        <div
          className="absolute -left-0.5 top-1/2 -translate-y-1/2 w-1 h-8 rounded-full"
          style={indicatorStyles}
        />
      )}

      <div className="flex items-start justify-between gap-4">
        <div className="flex-1 min-w-0">
          {/* 标题 */}
          <div className="flex items-center gap-2">
            {save.type === "multiplayer" ? (
              <Users
                className="w-4 h-4 shrink-0"
                style={{ color: color("primaryLight") }}
              />
            ) : (
              <Gamepad2
                className="w-4 h-4 shrink-0"
                style={{ color: color("primaryLight") }}
              />
            )}
            <h3
              className="font-medium truncate"
              style={{ color: color("textPrimary") }}
            >
              {save.name || "未命名存档"}
            </h3>
            {/* 类型标签 */}
            <span
              className="px-1.5 py-0.5 rounded text-xs shrink-0"
              style={{
                background: colorAlpha(
                  save.type === "multiplayer" ? "primary" : "primary",
                  0.15
                ),
                color: color("primaryLight"),
              }}
            >
              {save.type === "multiplayer" ? "👥 联机" : "🎮 单人"}
            </span>
          </div>

          {/* 元信息 */}
          <div
            className="flex items-center gap-3 mt-2 text-sm"
            style={{ color: colorAlpha("primary", 0.7) }}
          >
            <span className="flex items-center gap-1">
              <Clock className="w-3.5 h-3.5" />
              {formatRelativeTime(save.updatedAt)}
            </span>
            {isActive && (
              <span
                className="px-2 py-0.5 rounded text-xs"
                style={{
                  background: colorAlpha("primary", 0.2),
                  color: color("primaryLight"),
                }}
              >
                当前存档
              </span>
            )}
          </div>
        </div>

        {/* 操作按钮 */}
        <div className="flex items-center gap-2">
          <Button
            variant="ghost"
            size="sm"
            onClick={onLoad}
            disabled={isActive}
            style={{
              color: color("primaryLight"),
            }}
          >
            <Play className="w-4 h-4 mr-1" />
            {isActive ? "已加载" : "加载"}
          </Button>
          <Button
            variant="ghost"
            size="icon"
            onClick={onExport}
            className="opacity-0 group-hover:opacity-100 transition-opacity"
            style={{
              color: colorAlpha("primary", 0.7),
            }}
            title="导出存档"
          >
            <Download className="w-4 h-4" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            onClick={onDelete}
            className="opacity-0 group-hover:opacity-100 transition-opacity"
            style={{
              color: colorAlpha("error", 0.6),
            }}
            title="删除存档"
          >
            <Trash2 className="w-4 h-4" />
          </Button>
        </div>
      </div>
    </motion.div>
  );
}

/**
 * 新建存档按钮
 */
interface NewSaveButtonProps {
  onClick: () => void;
}

function NewSaveButton({ onClick }: NewSaveButtonProps) {
  return (
    <motion.button
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ delay: animation.duration.normal }}
      onClick={onClick}
      className={cn(
        "w-full p-4 border-2 border-dashed",
        `transition-all duration-[${animation.duration.normal * 1000}ms]`,
        "flex items-center justify-center gap-2"
      )}
      style={{
        borderRadius: borders.radius.lg,
        borderColor: colorAlpha("primary", 0.2),
        color: colorAlpha("primary", 0.7),
      }}
      onMouseEnter={(e) => {
        e.currentTarget.style.borderColor = colorAlpha("primary", 0.5);
        e.currentTarget.style.color = color("primaryLight");
        e.currentTarget.style.background = colorAlpha("primary", 0.05);
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.borderColor = colorAlpha("primary", 0.2);
        e.currentTarget.style.color = colorAlpha("primary", 0.7);
        e.currentTarget.style.background = "transparent";
      }}
    >
      <Plus className="w-5 h-5" />
      <span>新建存档</span>
    </motion.button>
  );
}

/**
 * 空状态
 */
function EmptyState({ onCreate }: { onCreate: () => void }) {
  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      className="flex flex-col items-center justify-center py-12 text-center"
    >
      <div
        className="w-16 h-16 rounded-full flex items-center justify-center mb-4"
        style={{
          background: gradients.subtle(),
          border: `2px solid ${colorAlpha("primary", 0.3)}`,
        }}
      >
        <FolderOpen
          className="w-8 h-8"
          style={{ color: colorAlpha("primary", 0.6) }}
        />
      </div>
      <h3
        className="font-medium mb-2"
        style={{ color: color("textSecondary") }}
      >
        暂无存档
      </h3>
      <p className="text-sm mb-6" style={{ color: color("textMuted") }}>
        开始你的冒险之旅吧
      </p>
      <Button onClick={onCreate} className="gap-2">
        <Plus className="w-4 h-4" />
        新建存档
      </Button>
    </motion.div>
  );
}

/**
 * SaveManagerDialog 主组件
 */
export function SaveManagerDialog({
  open,
  onOpenChange,
  onLoadSave,
  onMultiplayerSave,
}: SaveManagerDialogProps) {
  // 存档槽位数据（从 Yjs）
  const saves = useSaveSlots();

  // 当前存档 ID
  const currentSaveId = useCurrentSaveId();

  // 通过 CommandBus 发送命令（符合架构规范）
  const dispatch = useCommand();

  // 新建存档 - 通过 CommandBus
  const handleCreate = useCallback(async () => {
    const result = await dispatch({
      type: SaveCommands.CREATE_SAVE,
      payload: { name: `存档 ${saves.length + 1}` },
    });

    if (result.success && result.data) {
      onOpenChange(false);
      onLoadSave?.(result.data as string);
    }
  }, [dispatch, onOpenChange, onLoadSave, saves.length]);

  // 加载存档 - 通过 CommandBus
  const handleLoad = useCallback(
    async (save: SaveSlotInfo) => {
      // 联机存档：弹出选择对话框
      if (save.type === "multiplayer" && onMultiplayerSave) {
        onOpenChange(false);
        onMultiplayerSave(save);
        return;
      }

      // 单人存档：直接加载
      const result = await dispatch({
        type: SaveCommands.LOAD_SAVE,
        payload: { saveId: save.id },
      });

      if (result.success) {
        onOpenChange(false);
        onLoadSave?.(save.id);
      }
    },
    [dispatch, onOpenChange, onLoadSave, onMultiplayerSave]
  );

  // 删除存档 - 通过 CommandBus
  const handleDelete = useCallback(
    async (saveId: string) => {
      // TODO: 添加确认弹窗
      await dispatch({
        type: SaveCommands.DELETE_SAVE,
        payload: { saveId },
      });
    },
    [dispatch]
  );

  // Toast 提示
  const { toast } = useToast();

  // 导出单个存档 - 通过 CommandBus
  const handleExport = useCallback(
    async (save: SaveSlotInfo) => {
      try {
        const result = await dispatch({
          type: DataCommands.EXPORT_SAVE,
          payload: { saveId: save.id },
        });

        if (result.success) {
          toast("success", "导出成功", `已导出存档「${save.name}」`);
        } else {
          toast("error", "导出失败", result.error || "无法读取存档数据");
        }
      } catch (_error) {
        toast("error", "导出失败", "请稍后重试");
      }
    },
    [dispatch, toast]
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        title="存档管理"
        description="管理你的游戏存档"
        className="max-w-xl"
      >
        <div className="space-y-3 max-h-[60vh] overflow-y-auto pr-2 -mr-2">
          {saves.length === 0 ? (
            <EmptyState onCreate={handleCreate} />
          ) : (
            <div className="space-y-3">
              <AnimatePresence mode="popLayout">
                {saves.map((save, index) => (
                  <SaveCard
                    key={save.id}
                    save={save}
                    isActive={save.id === currentSaveId}
                    onLoad={() => handleLoad(save)}
                    onDelete={() => handleDelete(save.id)}
                    onExport={() => handleExport(save)}
                    index={index}
                  />
                ))}
              </AnimatePresence>
              <NewSaveButton onClick={handleCreate} />
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * AI 设置页面
 * 从原 Settings/index.tsx 拆分
 */

import { Button, Input, Select, Slider, ToggleCard } from "@/components/ui";
import {
  PROVIDER_PRESETS,
  aiManager,
  type ModelInfo,
  type ProviderType,
} from "@/lib/ai";
import { cn } from "@/lib/utils";
import { useSettingsStore } from "@/stores/settings";
import { animation, borders, color, colorAlpha } from "@/styles/tokens";
import { AnimatePresence, motion } from "framer-motion";
import {
  ArrowLeft,
  ArrowLeftRight,
  ChevronDown,
  Eye,
  EyeOff,
  Plug,
  RefreshCw,
} from "lucide-react";
import { useCallback, useEffect, useState } from "react";

interface AISettingsProps {
  onBack: () => void;
}

export function AISettings({ onBack }: AISettingsProps) {
  const { aiConfig, setAIConfig, setAdvancedSettings } = useSettingsStore();

  // 本地表单状态
  const [formData, setFormData] = useState(aiConfig);
  const [showApiKey, setShowApiKey] = useState(false);
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [models, setModels] = useState<ModelInfo[]>([]);
  const [loadingModels, setLoadingModels] = useState(false);
  const [testing, setTesting] = useState(false);
  const [testResult, setTestResult] = useState<boolean | null>(null);

  // 同步配置到表单
  useEffect(() => {
    setFormData(aiConfig);
    setTestResult(null);
  }, [aiConfig]);

  // 切换提供商
  const handleProviderChange = useCallback((provider: string) => {
    const preset = PROVIDER_PRESETS.find((p) => p.id === provider);
    if (preset) {
      setFormData((prev) => ({
        ...prev,
        provider: provider as ProviderType,
        baseUrl: preset.baseUrl,
        model: preset.defaultModel,
      }));
      setModels([]);
    }
  }, []);

  // 获取模型列表
  const fetchModels = useCallback(async () => {
    if (!formData.apiKey || !formData.baseUrl) return;

    setLoadingModels(true);
    try {
      const modelList = await aiManager.fetchModels(formData);
      setModels(modelList);
    } catch (_error) {
      setModels([]);
    } finally {
      setLoadingModels(false);
    }
  }, [formData]);

  // 测试连接
  const testConnection = useCallback(async () => {
    setTesting(true);
    setTestResult(null);
    try {
      const result = await aiManager.testConnection(formData);
      setTestResult(result);
    } catch {
      setTestResult(false);
    } finally {
      setTesting(false);
    }
  }, [formData]);

  // 保存设置
  const handleSave = useCallback(() => {
    setAIConfig({
      provider: formData.provider,
      baseUrl: formData.baseUrl,
      apiKey: formData.apiKey,
      model: formData.model,
    });
    setAdvancedSettings(formData.advanced);
    onBack();
  }, [formData, setAIConfig, setAdvancedSettings, onBack]);

  // 提供商选项
  const providerOptions = PROVIDER_PRESETS.map((p) => ({
    value: p.id,
    label: p.name,
  }));

  // 模型选项
  const modelOptions =
    models.length > 0
      ? models.map((m) => ({ value: m.id, label: m.name || m.id }))
      : [{ value: formData.model, label: formData.model }];

  return (
    <div className="space-y-4">
      {/* 返回按钮 */}
      <button
        type="button"
        onClick={onBack}
        className={cn(
          "flex items-center gap-2 text-sm font-medium",
          `transition-colors duration-[${animation.duration.fast * 1000}ms]`
        )}
        style={{ color: color("textSecondary") }}
        onMouseEnter={(e) => {
          e.currentTarget.style.color = color("primary");
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.color = color("textSecondary");
        }}
      >
        <ArrowLeft className="w-4 h-4" />
        返回
      </button>

      {/* 提供商 */}
      <div className="space-y-2">
        <label
          className="text-sm font-medium"
          style={{ color: color("textSecondary") }}
        >
          提供商
        </label>
        <Select
          value={formData.provider}
          onValueChange={handleProviderChange}
          options={providerOptions}
        />
      </div>

      {/* API 地址 */}
      <div className="space-y-2">
        <label
          className="text-sm font-medium"
          style={{ color: color("textSecondary") }}
        >
          API 地址
        </label>
        <Input
          value={formData.baseUrl}
          onChange={(e) =>
            setFormData((prev) => ({ ...prev, baseUrl: e.target.value }))
          }
          placeholder="https://api.openai.com"
        />
        <p className="text-xs" style={{ color: color("textMuted") }}>
          提示：可填写反向代理地址
        </p>
      </div>

      {/* API Key */}
      <div className="space-y-2">
        <label
          className="text-sm font-medium"
          style={{ color: color("textSecondary") }}
        >
          API Key
        </label>
        <div className="relative">
          <Input
            type={showApiKey ? "text" : "password"}
            value={formData.apiKey}
            onChange={(e) =>
              setFormData((prev) => ({ ...prev, apiKey: e.target.value }))
            }
            placeholder="sk-..."
            className="pr-10"
          />
          <button
            type="button"
            onClick={() => setShowApiKey(!showApiKey)}
            className="absolute right-3 top-1/2 -translate-y-1/2"
            style={{ color: color("textMuted") }}
            onMouseEnter={(e) => {
              e.currentTarget.style.color = color("textPrimary");
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.color = color("textMuted");
            }}
          >
            {showApiKey ? (
              <EyeOff className="w-4 h-4" />
            ) : (
              <Eye className="w-4 h-4" />
            )}
          </button>
        </div>
      </div>

      {/* 模型 */}
      <div className="space-y-2">
        <label
          className="text-sm font-medium"
          style={{ color: color("textSecondary") }}
        >
          模型
        </label>
        <div className="flex gap-2">
          <div className="flex-1">
            <Select
              value={formData.model}
              onValueChange={(value) =>
                setFormData((prev) => ({ ...prev, model: value }))
              }
              options={modelOptions}
              loading={loadingModels}
              placeholder={loadingModels ? "加载中..." : "选择模型"}
            />
          </div>
          <Button
            variant="outline"
            size="icon"
            onClick={fetchModels}
            disabled={!formData.apiKey || loadingModels}
            className="shrink-0"
          >
            <RefreshCw
              className={cn("w-4 h-4", loadingModels && "animate-spin")}
            />
          </Button>
        </div>
      </div>

      {/* 测试连接 */}
      <Button
        variant="outline"
        className="w-full"
        onClick={testConnection}
        disabled={!formData.apiKey || testing}
      >
        {testing ? (
          <>
            <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
            测试中...
          </>
        ) : (
          <>
            <Plug className="w-4 h-4 mr-2" />
            测试连接
          </>
        )}
      </Button>

      {/* 测试结果 */}
      <AnimatePresence>
        {testResult !== null && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="px-3 py-2 text-sm border"
            style={{
              borderRadius: borders.radius.md,
              background: testResult
                ? colorAlpha("success", 0.2)
                : colorAlpha("error", 0.2),
              color: testResult ? color("success") : color("error"),
              borderColor: testResult
                ? colorAlpha("success", 0.3)
                : colorAlpha("error", 0.3),
            }}
          >
            {testResult ? "✓ 连接成功" : "✗ 连接失败，请检查配置"}
          </motion.div>
        )}
      </AnimatePresence>

      {/* 高级设置折叠 */}
      <button
        type="button"
        onClick={() => setShowAdvanced(!showAdvanced)}
        className={cn(
          "flex items-center justify-between w-full py-2",
          "text-sm font-medium pt-4",
          `transition-colors duration-[${animation.duration.fast * 1000}ms]`
        )}
        style={{
          color: color("textSecondary"),
          borderTop: `2px solid ${colorAlpha("primary", 0.2)}`,
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.color = color("textPrimary");
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.color = color("textSecondary");
        }}
      >
        <span>▼ 高级设置</span>
        <ChevronDown
          className={cn(
            "w-4 h-4 transition-transform duration-200",
            showAdvanced && "rotate-180"
          )}
          style={{ color: color("primaryLight") }}
        />
      </button>

      {/* 高级设置面板 */}
      <AnimatePresence>
        {showAdvanced && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="space-y-4 overflow-hidden"
          >
            {/* 流式输出 */}
            <ToggleCard
              checked={formData.advanced.stream}
              onCheckedChange={(checked) =>
                setFormData((prev) => ({
                  ...prev,
                  advanced: { ...prev.advanced, stream: checked },
                }))
              }
              icon={<ArrowLeftRight className="w-5 h-5" />}
              title="流式输出"
              description="实时显示 AI 回复"
            />

            {/* 温度 */}
            <div className="space-y-2">
              <label
                className="text-sm font-medium"
                style={{ color: color("textSecondary") }}
              >
                温度 (Temperature)
              </label>
              <Slider
                value={formData.advanced.temperature}
                onValueChange={(value) =>
                  setFormData((prev) => ({
                    ...prev,
                    advanced: { ...prev.advanced, temperature: value },
                  }))
                }
                min={0}
                max={2}
                step={0.1}
              />
            </div>

            {/* 最大输出 Token */}
            <div className="space-y-2">
              <label
                className="text-sm font-medium"
                style={{ color: color("textSecondary") }}
              >
                最大输出 Token
              </label>
              <Input
                type="number"
                value={formData.advanced.maxTokens}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    advanced: {
                      ...prev.advanced,
                      maxTokens: parseInt(e.target.value) || 4096,
                    },
                  }))
                }
                min={1}
              />
            </div>

            {/* 上下文长度 */}
            <div className="space-y-2">
              <label
                className="text-sm font-medium"
                style={{ color: color("textSecondary") }}
              >
                上下文长度
              </label>
              <Input
                type="number"
                value={formData.advanced.contextLength}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    advanced: {
                      ...prev.advanced,
                      contextLength: parseInt(e.target.value) || 128000,
                    },
                  }))
                }
                min={1}
              />
            </div>

            {/* Top P */}
            <div className="space-y-2">
              <label
                className="text-sm font-medium"
                style={{ color: color("textSecondary") }}
              >
                Top P
              </label>
              <Slider
                value={formData.advanced.topP}
                onValueChange={(value) =>
                  setFormData((prev) => ({
                    ...prev,
                    advanced: { ...prev.advanced, topP: value },
                  }))
                }
                min={0}
                max={1}
                step={0.05}
              />
            </div>

            {/* 频率惩罚 */}
            <div className="space-y-2">
              <label
                className="text-sm font-medium"
                style={{ color: color("textSecondary") }}
              >
                频率惩罚 (Frequency Penalty)
              </label>
              <Slider
                value={formData.advanced.frequencyPenalty}
                onValueChange={(value) =>
                  setFormData((prev) => ({
                    ...prev,
                    advanced: { ...prev.advanced, frequencyPenalty: value },
                  }))
                }
                min={0}
                max={2}
                step={0.1}
              />
            </div>

            {/* 存在惩罚 */}
            <div className="space-y-2">
              <label
                className="text-sm font-medium"
                style={{ color: color("textSecondary") }}
              >
                存在惩罚 (Presence Penalty)
              </label>
              <Slider
                value={formData.advanced.presencePenalty}
                onValueChange={(value) =>
                  setFormData((prev) => ({
                    ...prev,
                    advanced: { ...prev.advanced, presencePenalty: value },
                  }))
                }
                min={0}
                max={2}
                step={0.1}
              />
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* 底部按钮 */}
      <div
        className="flex gap-2 pt-4"
        style={{ borderTop: `2px solid ${colorAlpha("primary", 0.2)}` }}
      >
        <Button variant="outline" className="flex-1" onClick={onBack}>
          取消
        </Button>
        <Button className="flex-1" onClick={handleSave}>
          保存
        </Button>
      </div>
    </div>
  );
}

/**
 * 数据管理页面
 * 导出/导入 + 存储空间监控
 */

import { Button } from "@/components/ui";
import { StorageIndicator } from "@/core/yjs";
import { DataCommands } from "@/domain/commands/data";
import { useCommand, useToast } from "@/hooks";
import { cn } from "@/lib/utils";
import { animation, color, colorAlpha } from "@/styles/tokens";
import { motion } from "framer-motion";
import { ArrowLeft, Download, HardDrive, Upload } from "lucide-react";
import { useCallback, useRef, useState } from "react";

interface DataManagementProps {
  onBack: () => void;
  onImportPreview?: (file: File) => void;
}

export function DataManagement({
  onBack,
  onImportPreview,
}: DataManagementProps) {
  const { toast } = useToast();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [exporting, setExporting] = useState(false);

  // 通过 CommandBus 发送命令
  const dispatch = useCommand();

  // 导出全部存档 - 通过 CommandBus
  const handleExportAll = useCallback(async () => {
    setExporting(true);
    try {
      const result = await dispatch({
        type: DataCommands.EXPORT_ALL,
        payload: {},
      });

      if (result.success) {
        toast("success", "导出成功", "已导出全部存档");
      } else {
        toast("error", "导出失败", result.error || "请稍后重试");
      }
    } catch (_error) {
      toast("error", "导出失败", "请稍后重试");
    } finally {
      setExporting(false);
    }
  }, [dispatch, toast]);

  // 选择文件导入
  const handleFileSelect = useCallback(() => {
    fileInputRef.current?.click();
  }, []);

  // 文件选择后处理
  const handleFileChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
        if (onImportPreview) {
          onImportPreview(file);
        } else {
          toast("info", "导入功能", "导入预览功能即将推出");
        }
      }
      // 重置 input 以便可以再次选择同一文件
      e.target.value = "";
    },
    [onImportPreview, toast]
  );

  return (
    <div className="space-y-4">
      {/* 返回按钮 */}
      <button
        type="button"
        onClick={onBack}
        className={cn(
          "flex items-center gap-2 text-sm font-medium",
          `transition-colors duration-[${animation.duration.fast * 1000}ms]`
        )}
        style={{ color: color("textSecondary") }}
        onMouseEnter={(e) => {
          e.currentTarget.style.color = color("primary");
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.color = color("textSecondary");
        }}
      >
        <ArrowLeft className="w-4 h-4" />
        返回
      </button>

      {/* 导出数据卡片 */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        className="rounded-lg p-4"
        style={{
          background: colorAlpha("bgElevated", 0.5),
          border: `1px solid ${colorAlpha("primary", 0.2)}`,
        }}
      >
        <div className="flex items-start gap-3 mb-3">
          <Download
            className="w-5 h-5 mt-0.5"
            style={{ color: color("primary") }}
          />
          <div className="flex-1">
            <h3
              className="text-sm font-semibold mb-1"
              style={{ color: color("textPrimary") }}
            >
              导出数据
            </h3>
            <p className="text-sm" style={{ color: color("textSecondary") }}>
              将游戏数据导出为 JSON 文件，可用于备份或迁移
            </p>
          </div>
        </div>

        <div className="flex justify-end">
          <Button
            variant="outline"
            size="sm"
            onClick={handleExportAll}
            disabled={exporting}
          >
            {exporting ? "导出中..." : "导出全部存档"}
          </Button>
        </div>
      </motion.div>

      {/* 提示信息 */}
      <p className="text-xs px-1" style={{ color: color("textMuted") }}>
        提示：单个存档可在「存档管理」中导出
      </p>

      {/* 导入数据卡片 */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.1 }}
        className="rounded-lg p-4"
        style={{
          background: colorAlpha("bgElevated", 0.5),
          border: `1px solid ${colorAlpha("primary", 0.2)}`,
        }}
      >
        <div className="flex items-start gap-3 mb-3">
          <Upload
            className="w-5 h-5 mt-0.5"
            style={{ color: color("secondary") }}
          />
          <div className="flex-1">
            <h3
              className="text-sm font-semibold mb-1"
              style={{ color: color("textPrimary") }}
            >
              导入数据
            </h3>
            <p className="text-sm" style={{ color: color("textSecondary") }}>
              从 JSON 文件导入游戏数据
            </p>
            <p className="text-xs mt-1" style={{ color: color("textMuted") }}>
              导入的存档将生成新 ID，不会覆盖现有数据
            </p>
          </div>
        </div>

        <div className="flex justify-end">
          <Button variant="outline" size="sm" onClick={handleFileSelect}>
            选择文件导入
          </Button>
        </div>

        {/* 隐藏的文件输入 */}
        <input
          ref={fileInputRef}
          type="file"
          accept=".json"
          onChange={handleFileChange}
          className="hidden"
        />
      </motion.div>

      {/* 存储空间卡片 */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.2 }}
        className="rounded-lg p-4"
        style={{
          background: colorAlpha("bgElevated", 0.5),
          border: `1px solid ${colorAlpha("primary", 0.2)}`,
        }}
      >
        <div className="flex items-center gap-2 mb-3">
          <HardDrive className="w-5 h-5" style={{ color: color("primary") }} />
          <h3
            className="text-sm font-semibold"
            style={{ color: color("textPrimary") }}
          >
            存储空间
          </h3>
        </div>

        <StorageIndicator />
      </motion.div>
    </div>
  );
}

/**
 * 导入预览弹窗
 * 显示导入文件的预览信息，确认后执行导入
 */

import { Button } from "@/components/ui";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import { DataCommands } from "@/domain/commands/data";
import { SaveCommands } from "@/domain/commands/save";
import { useCommand, useToast } from "@/hooks";
import type {
  ExportData,
  ImportPreview as ImportPreviewType,
} from "@/modules/data";
import { color, colorAlpha } from "@/styles/tokens";
import { motion } from "framer-motion";
import {
  AlertTriangle,
  Calendar,
  FileJson,
  Gamepad2,
  MessageSquare,
  MessagesSquare,
} from "lucide-react";
import { useCallback, useState } from "react";

interface ImportPreviewProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  preview: ImportPreviewType | null;
  data: ExportData | null;
  onImportComplete?: () => void;
}

/**
 * 格式化相对时间
 */
function formatRelativeTime(timestamp: number): string {
  const now = Date.now();
  const diff = now - timestamp;

  const seconds = Math.floor(diff / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);

  if (days > 0) return days === 1 ? "昨天" : `${days}天前`;
  if (hours > 0) return `${hours}小时前`;
  if (minutes > 0) return `${minutes}分钟前`;
  return "刚刚";
}

/**
 * 格式化日期时间
 */
function formatDateTime(timestamp: number): string {
  const date = new Date(timestamp);
  return date.toLocaleString("zh-CN", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

/**
 * 获取导出类型显示名称
 */
function getExportTypeName(type: string): string {
  switch (type) {
    case "single_save":
      return "单个存档";
    case "full_backup":
      return "全部数据备份";
    default:
      return "未知类型";
  }
}

export function ImportPreview({
  open,
  onOpenChange,
  preview,
  data,
  onImportComplete,
}: ImportPreviewProps) {
  const { toast } = useToast();
  const dispatch = useCommand();
  const [importing, setImporting] = useState(false);

  // 执行导入
  const handleImport = useCallback(async () => {
    if (!data) return;

    setImporting(true);
    try {
      const result = await dispatch({
        type: DataCommands.IMPORT_DATA,
        payload: { data },
      });

      if (result.success) {
        const saveCount = Object.keys(result.data || {}).length;
        toast("success", "导入成功", `已导入 ${saveCount} 个存档`);

        const saveIdMap = (result.data || {}) as Record<string, string>;
        let targetSaveId: string | null = null;

        if (data.type === "single_save") {
          targetSaveId = saveIdMap[data.save.id] || null;
        } else {
          const latestSave = [...data.saves].sort(
            (a, b) => b.updatedAt - a.updatedAt
          )[0];
          if (latestSave) {
            targetSaveId = saveIdMap[latestSave.id] || null;
          }
        }

        if (targetSaveId) {
          const loadResult = await dispatch({
            type: SaveCommands.LOAD_SAVE,
            payload: { saveId: targetSaveId },
          });

          if (!loadResult.success) {
            toast("warning", "自动加载失败", "请在存档管理中手动加载");
          }
        }

        onOpenChange(false);
        onImportComplete?.();
      } else {
        toast("error", "导入失败", result.error || "请稍后重试");
      }
    } catch (_error) {
      toast("error", "导入失败", "请稍后重试");
    } finally {
      setImporting(false);
    }
  }, [data, dispatch, toast, onOpenChange, onImportComplete]);

  // 取消导入
  const handleCancel = useCallback(() => {
    onOpenChange(false);
  }, [onOpenChange]);

  if (!preview) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent title="导入预览" className="max-w-md">
        <div className="space-y-4">
          {/* 文件信息卡片 */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="rounded-lg p-4"
            style={{
              background: colorAlpha("bgElevated", 0.5),
              border: `1px solid ${colorAlpha("primary", 0.2)}`,
            }}
          >
            <div className="flex items-center gap-2 mb-3">
              <FileJson
                className="w-5 h-5"
                style={{ color: color("primary") }}
              />
              <h3
                className="text-sm font-semibold"
                style={{ color: color("textPrimary") }}
              >
                文件信息
              </h3>
            </div>

            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span style={{ color: color("textSecondary") }}>类型</span>
                <span style={{ color: color("textPrimary") }}>
                  {getExportTypeName(preview.type)}
                </span>
              </div>
              <div className="flex justify-between">
                <span style={{ color: color("textSecondary") }}>导出时间</span>
                <span style={{ color: color("textPrimary") }}>
                  {formatDateTime(preview.exportedAt)}
                </span>
              </div>
              <div className="flex justify-between">
                <span style={{ color: color("textSecondary") }}>存档数量</span>
                <span style={{ color: color("textPrimary") }}>
                  {preview.saveCount} 个
                </span>
              </div>
            </div>
          </motion.div>

          {/* 存档列表卡片 */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="rounded-lg p-4"
            style={{
              background: colorAlpha("bgElevated", 0.5),
              border: `1px solid ${colorAlpha("primary", 0.2)}`,
            }}
          >
            <div className="flex items-center gap-2 mb-3">
              <Gamepad2
                className="w-5 h-5"
                style={{ color: color("secondary") }}
              />
              <h3
                className="text-sm font-semibold"
                style={{ color: color("textPrimary") }}
              >
                存档列表
              </h3>
            </div>

            <div className="space-y-2 max-h-48 overflow-y-auto pr-1">
              {preview.saves.map((save, index) => (
                <motion.div
                  key={index}
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.15 + index * 0.05 }}
                  className="rounded-md p-3"
                  style={{
                    background: colorAlpha("primary", 0.05),
                    border: `1px solid ${colorAlpha("primary", 0.1)}`,
                  }}
                >
                  <div className="flex items-center gap-2 mb-1">
                    <Gamepad2
                      className="w-4 h-4"
                      style={{ color: color("primaryLight") }}
                    />
                    <span
                      className="font-medium text-sm truncate"
                      style={{ color: color("textPrimary") }}
                    >
                      {save.name || "未命名存档"}
                    </span>
                  </div>
                  <div
                    className="flex items-center gap-3 text-xs"
                    style={{ color: color("textMuted") }}
                  >
                    <span className="flex items-center gap-1">
                      <MessagesSquare className="w-3 h-3" />
                      {save.conversationCount} 个会话
                    </span>
                    <span className="flex items-center gap-1">
                      <MessageSquare className="w-3 h-3" />
                      {save.messageCount} 条消息
                    </span>
                    <span className="flex items-center gap-1">
                      <Calendar className="w-3 h-3" />
                      {formatRelativeTime(save.updatedAt)}
                    </span>
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.div>

          {/* 导入说明卡片 */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
            className="rounded-lg p-4"
            style={{
              background: colorAlpha("warning", 0.1),
              border: `1px solid ${colorAlpha("warning", 0.3)}`,
            }}
          >
            <div className="flex items-start gap-2">
              <AlertTriangle
                className="w-5 h-5 mt-0.5 shrink-0"
                style={{ color: color("warning") }}
              />
              <div>
                <h3
                  className="text-sm font-semibold mb-1"
                  style={{ color: color("warning") }}
                >
                  导入说明
                </h3>
                <p
                  className="text-sm"
                  style={{ color: color("textSecondary") }}
                >
                  导入的存档将生成新 ID，不会覆盖现有数据
                </p>
              </div>
            </div>
          </motion.div>

          {/* 操作按钮 */}
          <div className="flex justify-end gap-3 pt-2">
            <Button variant="ghost" onClick={handleCancel} disabled={importing}>
              取消
            </Button>
            <Button onClick={handleImport} disabled={importing}>
              {importing ? "导入中..." : "确认导入"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import {
  commandBus,
  type CommandContext,
  type CommandHandler,
} from "../command-bus";
import { eventBus, type EventHandler } from "../event-bus";

/**
 * 模块生命周期钩子（Phase 3 启用）
 */
export interface ModuleLifecycle {
  /** 模块加载时调用 */
  onLoad?: () => Promise<void>;
  /** 依赖就绪后调用 */
  onInit?: (context: ModuleContext) => Promise<void>;
  /** 模块可以开始工作时调用 */
  onStart?: () => Promise<void>;
  /** 模块准备卸载时调用 */
  onStop?: () => Promise<void>;
  /** 模块卸载后清理资源 */
  onUnload?: () => Promise<void>;
}

/**
 * 模块上下文（传递给生命周期钩子）
 */
export interface ModuleContext {
  /** 模块 ID */
  moduleId: string;
  /** 获取其他模块（通过依赖） */
  getModule: (id: string) => ModuleManifest | undefined;
  /** 事件总线 */
  eventBus: typeof eventBus;
  /** 命令总线 */
  commandBus: typeof commandBus;
}

/**
 * 模块清单 - 每个模块必须声明
 */
export interface ModuleManifest extends Partial<ModuleLifecycle> {
  /** 模块唯一标识 e.g. "lyra.chat" */
  id: string;
  /** 模块版本 */
  version?: string;
  /** 依赖的其他模块 ID */
  dependencies?: string[];
  /** 命令处理器 */
  commands?: Record<string, CommandHandler<unknown, unknown>>;
  /** 事件处理器 */
  eventHandlers?: Record<string, EventHandler<unknown>>;
  /** AI 工具定义（Phase 4 启用） */
  aiTools?: AIToolDefinition[];
  /** 模块提供的能力声明 */
  provides?: ModuleCapabilities;
  /** 模块需要的能力声明 */
  requires?: ModuleRequirements;
}

/**
 * AI 工具定义
 */
export interface AIToolDefinition {
  name: string;
  description: string;
  parameters: Record<string, unknown>;
  handler: (args: unknown, context: CommandContext) => Promise<unknown>;
}

/**
 * 模块提供的能力
 */
export interface ModuleCapabilities {
  commands?: string[];
  events?: string[];
  entities?: string[];
}

/**
 * 模块需要的能力
 */
export interface ModuleRequirements {
  events?: string[];
  entities?: string[];
}

/**
 * 模块状态
 */
export type ModuleStatus =
  | "pending"
  | "loading"
  | "loaded"
  | "started"
  | "stopped"
  | "error";

/**
 * 已注册模块的状态
 */
interface RegisteredModule {
  manifest: ModuleManifest;
  status: ModuleStatus;
  unsubscribers: Array<() => void>;
  loadedAt?: number;
  error?: string;
}

/**
 * 模块注册表
 *
 * Phase 1: 基础注册/注销
 * Phase 3: 生命周期管理、依赖解析
 * Phase 6: 沙箱隔离、权限控制
 */
class ModuleRegistryImpl {
  private modules = new Map<string, RegisteredModule>();
  private loadOrder: string[] = [];

  /**
   * 注册模块
   */
  async register(manifest: ModuleManifest): Promise<void> {
    if (this.modules.has(manifest.id)) {
      console.warn(
        `[Registry] Module ${manifest.id} already registered, replacing...`
      );
      await this.unregister(manifest.id);
    }

    const registeredModule: RegisteredModule = {
      manifest,
      status: "pending",
      unsubscribers: [],
    };

    this.modules.set(manifest.id, registeredModule);

    try {
      // Phase 1: 简化版，直接注册不做依赖检查
      // Phase 3 将添加: 依赖解析、拓扑排序

      registeredModule.status = "loading";

      // 调用 onLoad 钩子（如果有）
      if (manifest.onLoad) {
        await manifest.onLoad();
      }

      // 注册命令处理器
      if (manifest.commands) {
        for (const [type, handler] of Object.entries(manifest.commands)) {
          commandBus.register(type, handler);
          registeredModule.unsubscribers.push(() =>
            commandBus.unregister(type)
          );
        }
      }

      // 注册事件处理器
      if (manifest.eventHandlers) {
        for (const [type, handler] of Object.entries(manifest.eventHandlers)) {
          const unsubscribe = eventBus.on(type, handler);
          registeredModule.unsubscribers.push(unsubscribe);
        }
      }

      // 调用 onInit 钩子（如果有）
      if (manifest.onInit) {
        const context: ModuleContext = {
          moduleId: manifest.id,
          getModule: (id) => this.getModule(id),
          eventBus,
          commandBus,
        };
        await manifest.onInit(context);
      }

      registeredModule.status = "loaded";
      registeredModule.loadedAt = Date.now();
      this.loadOrder.push(manifest.id);

      // 调用 onStart 钩子（如果有）
      if (manifest.onStart) {
        await manifest.onStart();
        registeredModule.status = "started";
      }

      // Module registered successfully
    } catch (error) {
      registeredModule.status = "error";
      registeredModule.error =
        error instanceof Error ? error.message : "Unknown error";
      throw error;
    }
  }

  /**
   * 注销模块
   */
  async unregister(id: string): Promise<boolean> {
    const module = this.modules.get(id);
    if (!module) {
      return false;
    }

    // Phase 3 将添加: 依赖检查，被依赖时禁止卸载

    try {
      // 调用 onStop 钩子
      if (module.manifest.onStop) {
        await module.manifest.onStop();
      }

      // 清理所有订阅
      module.unsubscribers.forEach((unsub) => unsub());

      // 调用 onUnload 钩子
      if (module.manifest.onUnload) {
        await module.manifest.onUnload();
      }

      this.modules.delete(id);
      this.loadOrder = this.loadOrder.filter((m) => m !== id);

      return true;
    } catch (_error) {
      return false;
    }
  }

  /**
   * 获取模块
   */
  getModule(id: string): ModuleManifest | undefined {
    return this.modules.get(id)?.manifest;
  }

  /**
   * 获取模块状态
   */
  getModuleStatus(id: string): ModuleStatus | undefined {
    return this.modules.get(id)?.status;
  }

  /**
   * 获取所有已注册模块
   */
  getAllModules(): ModuleManifest[] {
    return Array.from(this.modules.values()).map((m) => m.manifest);
  }

  /**
   * 获取模块加载顺序
   */
  getLoadOrder(): string[] {
    return [...this.loadOrder];
  }

  /**
   * 检查模块是否已注册
   */
  hasModule(id: string): boolean {
    return this.modules.has(id);
  }

  /**
   * 检查模块是否已启动
   */
  isModuleStarted(id: string): boolean {
    return this.modules.get(id)?.status === "started";
  }

  /**
   * 获取依赖此模块的其他模块
   */
  getDependents(id: string): string[] {
    const dependents: string[] = [];
    for (const [moduleId, module] of this.modules) {
      if (module.manifest.dependencies?.includes(id)) {
        dependents.push(moduleId);
      }
    }
    return dependents;
  }

  /**
   * 清除所有模块（测试用）
   */
  async clear(): Promise<void> {
    // 按加载顺序逆序卸载
    const reversed = [...this.loadOrder].reverse();
    for (const id of reversed) {
      await this.unregister(id);
    }
  }
}

