/**
 * Yjs/IndexedDB 错误处理组件
 */

import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogFooter } from "@/components/ui/dialog";
import { color, colorAlpha } from "@/styles/tokens";
import { AlertTriangle, Database, RefreshCw } from "lucide-react";

export type StorageErrorType =
  | "indexeddb-not-supported"
  | "indexeddb-blocked"
  | "indexeddb-quota-exceeded"
  | "indexeddb-unknown";

interface StorageErrorInfo {
  type: StorageErrorType;
  title: string;
  description: string;
  suggestion: string;
  canRetry: boolean;
}

const ERROR_INFO: Record<StorageErrorType, Omit<StorageErrorInfo, "type">> = {
  "indexeddb-not-supported": {
    title: "浏览器不支持本地存储",
    description:
      "你的浏览器不支持 IndexedDB，无法保存游戏进度。这可能是因为浏览器版本过旧或处于隐私模式。",
    suggestion:
      "请使用 Chrome 89+ / Firefox 111+ / Safari 15.2+ / Edge 89+ 等现代浏览器，并确保未处于隐私/无痕模式。",
    canRetry: false,
  },
  "indexeddb-blocked": {
    title: "存储访问被阻止",
    description:
      "浏览器阻止了对本地存储的访问。这可能是因为隐私设置、浏览器扩展或企业策略。",
    suggestion:
      "请检查浏览器设置，确保允许网站使用本地存储。如果使用了隐私扩展，请将本站加入白名单。",
    canRetry: true,
  },
  "indexeddb-quota-exceeded": {
    title: "存储空间不足",
    description: "本地存储空间已满，无法保存更多数据。",
    suggestion: "请清理浏览器缓存或删除不需要的存档，释放存储空间后重试。",
    canRetry: true,
  },
  "indexeddb-unknown": {
    title: "存储初始化失败",
    description: "初始化本地存储时发生未知错误。",
    suggestion: "请刷新页面重试。如果问题持续，请尝试清除浏览器缓存。",
    canRetry: true,
  },
};

interface StorageErrorDialogProps {
  open: boolean;
  errorType: StorageErrorType;
  onRetry?: () => void;
  onDismiss?: () => void;
}

/**
 * 存储错误对话框
 */
export function StorageErrorDialog({
  open,
  errorType,
  onRetry,
  onDismiss,
}: StorageErrorDialogProps) {
  const info = ERROR_INFO[errorType];

  return (
    <Dialog open={open} onOpenChange={() => onDismiss?.()}>
      <DialogContent title={info.title} className="max-w-md">
        {/* 图标 */}
        <div className="flex justify-center mb-4">
          <div
            className="p-4 rounded-full"
            style={{
              background: colorAlpha("error", 0.15),
            }}
          >
            {errorType === "indexeddb-quota-exceeded" ? (
              <Database
                className="w-12 h-12"
                style={{ color: color("error") }}
              />
            ) : (
              <AlertTriangle
                className="w-12 h-12"
                style={{ color: color("error") }}
              />
            )}
          </div>
        </div>

        {/* 描述 */}
        <p
          className="text-center mb-4"
          style={{ color: color("textSecondary") }}
        >
          {info.description}
        </p>

        {/* 建议 */}
        <div
          className="p-3 rounded-lg mb-4"
          style={{
            background: colorAlpha("warning", 0.1),
            border: `1px solid ${colorAlpha("warning", 0.3)}`,
          }}
        >
          <p className="text-sm" style={{ color: color("warning") }}>
            提示：{info.suggestion}
          </p>
        </div>

        {/* 操作按钮 */}
        <DialogFooter>
          {info.canRetry && onRetry && (
            <Button onClick={onRetry} variant="default">
              <RefreshCw className="w-4 h-4 mr-2" />
              重试
            </Button>
          )}
          {onDismiss && (
            <Button onClick={onDismiss} variant="ghost">
              {info.canRetry ? "取消" : "我知道了"}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * 检测 IndexedDB 错误类型
 */
export function detectStorageErrorType(error: unknown): StorageErrorType {
  if (error instanceof Error) {
    const message = error.message.toLowerCase();
    const name = error.name.toLowerCase();

    // 配额超限
    if (
      name === "quotaexceedederror" ||
      message.includes("quota") ||
      message.includes("storage")
    ) {
      return "indexeddb-quota-exceeded";
    }

    // 访问被阻止
    if (
      name === "securityerror" ||
      message.includes("blocked") ||
      message.includes("denied") ||
      message.includes("security")
    ) {
      return "indexeddb-blocked";
    }
  }

  return "indexeddb-unknown";
}

/**
 * 检测 IndexedDB 是否真正可用（不仅仅是 API 存在）
 * 返回 null 表示可用，否则返回错误类型
 */
export async function checkIndexedDBAvailability(): Promise<StorageErrorType | null> {
  // 1. 检查 API 是否存在
  if (typeof indexedDB === "undefined") {
    return "indexeddb-not-supported";
  }

  // 2. 尝试打开一个测试数据库
  try {
    const testDbName = "__lyra_idb_test__";

    await new Promise<void>((resolve, reject) => {
      const request = indexedDB.open(testDbName, 1);

      request.onerror = () => {
        reject(request.error);
      };

      request.onsuccess = () => {
        // 成功打开，关闭并删除测试数据库
        request.result.close();
        const deleteRequest = indexedDB.deleteDatabase(testDbName);
        deleteRequest.onsuccess = () => resolve();
        deleteRequest.onerror = () => resolve(); // 删除失败也算成功
      };

      request.onblocked = () => {
        reject(new Error("IndexedDB blocked"));
      };
    });

    return null; // 可用
  } catch (error) {
    return detectStorageErrorType(error);
  }
}

/**
 * Yjs 文档管理器
 * 负责 Yjs 文档的创建、初始化、存档管理等核心功能
 */

import { IndexeddbPersistence } from "y-indexeddb";
import * as Y from "yjs";
import { CURRENT_VERSION, runMigrations } from "./migrations";
import type {
  CreateSaveParams,
  ExportConversationData,
  ExportMessageData,
  ExportSaveData,
  ImportSaveData,
  SaveMemberInfo,
  SaveSlotInfo,
  SaveType,
  YjsInitOptions,
} from "./types";

/**
 * 默认文档名称
 */
const DEFAULT_DOC_NAME = "lyra-game";

/**
 * localStorage key for current save ID
 */
const CURRENT_SAVE_KEY = "lyra-current-save-id";

/**
 * YjsManager 类
 */
export class YjsManager {
  private doc: Y.Doc | null = null;
  private provider: IndexeddbPersistence | null = null;
  private currentSaveId: string | null = null;
  private initialized = false;

  /**
   * 初始化 Yjs 文档
   */
  async init(options: YjsInitOptions = {}): Promise<void> {
    if (this.initialized) {
      return;
    }

    const docName = options.docName || DEFAULT_DOC_NAME;

    // 1. 创建 Yjs 文档
    this.doc = new Y.Doc();

    // 2. 创建 IndexedDB Provider
    this.provider = new IndexeddbPersistence(docName, this.doc);

    // 3. 等待 Provider 同步完成
    await new Promise<void>((resolve, reject) => {
      if (!this.provider) {
        reject(new Error("Provider not initialized"));
        return;
      }

      const timeout = setTimeout(() => {
        reject(new Error("IndexedDB sync timeout"));
      }, 10000); // 10s 超时

      this.provider.once("synced", () => {
        clearTimeout(timeout);
        resolve();
      });
    });

    // 4. 初始化根文档结构
    this.initRootStructure();

    // 5. 检查并执行数据迁移
    await this.checkAndMigrate();

    // 6. 恢复上次的存档 ID
    this.restoreCurrentSave();

    this.initialized = true;
  }

  /**
   * 恢复上次的存档 ID
   */
  private restoreCurrentSave(): void {
    try {
      const savedId = localStorage.getItem(CURRENT_SAVE_KEY);
      if (savedId) {
        const saves = this.getSaveSlots();
        if (saves.has(savedId)) {
          this.currentSaveId = savedId;
        } else {
          // 存档已被删除，清除 localStorage
          localStorage.removeItem(CURRENT_SAVE_KEY);
        }
      }
    } catch (_error) {
      // Silently ignore restore errors
    }
  }

  /**
   * 持久化当前存档 ID
   */
  private persistCurrentSave(): void {
    try {
      if (this.currentSaveId) {
        localStorage.setItem(CURRENT_SAVE_KEY, this.currentSaveId);
      } else {
        localStorage.removeItem(CURRENT_SAVE_KEY);
      }
    } catch (_error) {
      // Silently ignore persist errors
    }
  }

  /**
   * 初始化根文档结构
   */
  private initRootStructure(): void {
    if (!this.doc) return;

    const root = this.doc.getMap("root");

    // 初始化 version
    if (!root.has("version")) {
      root.set("version", CURRENT_VERSION);
    }

    // 初始化 saves
    if (!root.has("saves")) {
      root.set("saves", new Y.Map());
    }

    // 初始化 settings
    if (!root.has("settings")) {
      root.set("settings", new Y.Map());
    }

    // 初始化 assets
    if (!root.has("assets")) {
      root.set("assets", new Y.Map());
    }
  }

  /**
   * 检查并执行数据迁移
   */
  private async checkAndMigrate(): Promise<void> {
    if (!this.doc) return;

    const root = this.doc.getMap("root");
    const version = (root.get("version") as number) || 0;

    if (version < CURRENT_VERSION) {
      const result = await runMigrations(root, version, CURRENT_VERSION);

      if (!result.success) {
        // 迁移失败时仍然更新版本号，避免重复尝试失败的迁移
        root.set("version", CURRENT_VERSION);
      }
    }
  }

  /**
   * 获取 Yjs 文档
   */
  getDoc(): Y.Doc {
    if (!this.doc) {
      throw new Error("[YjsManager] Document not initialized");
    }
    return this.doc;
  }

  /**
   * 获取存档槽位 Map
   */
  getSaveSlots(): Y.Map<unknown> {
    const doc = this.getDoc();
    const root = doc.getMap("root");
    return root.get("saves") as Y.Map<unknown>;
  }

  /**
   * 获取所有存档信息（用于 UI 显示）
   */
  listSaves(): SaveSlotInfo[] {
    const saves = this.getSaveSlots();
    const result: SaveSlotInfo[] = [];

    saves.forEach((value, key) => {
      const saveMap = value as Y.Map<unknown>;

      // 从 Y.Map 中读取数据并转换为普通类型
      const id = saveMap.get("id") as string;
      const name = saveMap.get("name") as string;
      const createdAt = saveMap.get("createdAt") as number;
      const updatedAt = saveMap.get("updatedAt") as number;
      const type = (saveMap.get("type") as SaveType) || "solo";

      // 联机存档专用字段
      const sessionId = saveMap.get("sessionId") as string | undefined;
      const roomId = saveMap.get("roomId") as string | undefined;
      const lastRoomId = saveMap.get("lastRoomId") as string | undefined;
      const lastRoomCode = saveMap.get("lastRoomCode") as string | undefined;
      const memberCount = saveMap.get("memberCount") as number | undefined;
      const members = saveMap.get("members") as SaveMemberInfo[] | undefined;
      const maxPlayers = saveMap.get("maxPlayers") as number | undefined;
      const turnDuration = saveMap.get("turnDuration") as number | undefined;

      // 游戏进度字段（Phase 1 新增）
      const currentTurnNumber = saveMap.get("currentTurnNumber") as
        | number
        | undefined;

      result.push({
        id: id || key, // 如果没有 id 字段，使用 key
        name: name || "未命名存档",
        createdAt: Number(createdAt) || 0,
        updatedAt: Number(updatedAt) || 0,
        type,
        // 联机存档专用字段（仅在存在时添加）
        ...(sessionId && { sessionId }),
        ...(roomId && { roomId }),
        ...(lastRoomId && { lastRoomId }),
        ...(lastRoomCode && { lastRoomCode }),
        ...(memberCount !== undefined && { memberCount }),
        ...(members && { members }),
        ...(maxPlayers !== undefined && { maxPlayers }),
        ...(turnDuration !== undefined && { turnDuration }),
        // 游戏进度字段
        ...(currentTurnNumber !== undefined && { currentTurnNumber }),
      });
    });

    // 按更新时间倒序排序
    return result.sort((a, b) => b.updatedAt - a.updatedAt);
  }

  /**
   * 创建新存档
   */
  createSave(params: CreateSaveParams): string {
    const saves = this.getSaveSlots();
    const saveId = crypto.randomUUID();
    const now = Date.now();

    // 确定存档类型，默认为 'solo'
    const saveType: SaveType = params.type || "solo";

    // 创建存档对象（使用普通对象，Yjs 会自动转换）
    const saveData: Record<string, unknown> = {
      id: saveId,
      name: params.name,
      createdAt: now,
      updatedAt: now,
      type: saveType,
      conversations: new Y.Map(),
      messages: new Y.Map(),
      gameState: new Y.Map(),
    };

    // 联机存档专用字段
    if (saveType === "multiplayer") {
      // 生成或使用传入的 sessionId（兼容旧逻辑）
      saveData.sessionId = params.sessionId || crypto.randomUUID();
      if (params.roomId) {
        saveData.roomId = params.roomId;
        // 同时设置 lastRoomId（用于消息迁移判断）
        saveData.lastRoomId = params.roomId;
      }
      if (params.roomCode) {
        saveData.lastRoomCode = params.roomCode;
      }
      if (params.members) {
        saveData.members = params.members;
        saveData.memberCount = params.members.length;
      }
    }

    // 创建存档 Map 并设置数据
    const saveMap = new Y.Map();
    Object.entries(saveData).forEach(([key, value]) => {
      saveMap.set(key, value);
    });

    // 添加到 saves
    saves.set(saveId, saveMap);

    return saveId;
  }

  /**
   * 使用指定 ID 创建存档
   *
   * 用于 Guest 加入房间时创建与 Host 相同 saveId 的存档
   * 这样所有玩家的存档使用相同的 ID，匹配简单可靠
   *
   * @param saveId 指定的存档 ID（通常从 MainDoc 读取）
   * @param params 存档创建参数
   * @returns 存档 ID（与传入的 saveId 相同）
   */
  createSaveWithId(saveId: string, params: CreateSaveParams): string {
    const saves = this.getSaveSlots();
    const now = Date.now();

    // 检查是否已存在相同 ID 的存档
    if (saves.has(saveId)) {
      return saveId;
    }

    // 确定存档类型，默认为 'solo'
    const saveType: SaveType = params.type || "solo";

    // 创建存档对象（使用普通对象，Yjs 会自动转换）
    const saveData: Record<string, unknown> = {
      id: saveId, // 使用指定的 saveId
      name: params.name,
      createdAt: now,
      updatedAt: now,
      type: saveType,
      conversations: new Y.Map(),
      messages: new Y.Map(),
      gameState: new Y.Map(),
    };

    // 联机存档专用字段
    if (saveType === "multiplayer") {
      // 生成或使用传入的 sessionId（兼容旧逻辑）
      saveData.sessionId = params.sessionId || crypto.randomUUID();
      if (params.roomId) {
        saveData.roomId = params.roomId;
        // 同时设置 lastRoomId（用于消息迁移判断）
        saveData.lastRoomId = params.roomId;
      }
      if (params.roomCode) {
        saveData.lastRoomCode = params.roomCode;
      }
      if (params.members) {
        saveData.members = params.members;
        saveData.memberCount = params.members.length;
      }
    }

    // 创建存档 Map 并设置数据
    const saveMap = new Y.Map();
    Object.entries(saveData).forEach(([key, value]) => {
      saveMap.set(key, value);
    });

    // 添加到 saves（使用指定的 saveId 作为 key）
    saves.set(saveId, saveMap);

    return saveId;
  }

  /**
   * 加载存档
   */
  loadSave(saveId: string): void {
    const saves = this.getSaveSlots();

    if (!saves.has(saveId)) {
      throw new Error(`[YjsManager] Save not found: ${saveId}`);
    }

    this.currentSaveId = saveId;
    this.persistCurrentSave();
  }

  /**
   * 获取当前存档
   */
  getCurrentSave(): Y.Map<unknown> | null {
    if (!this.currentSaveId) {
      return null;
    }

    const saves = this.getSaveSlots();
    return saves.get(this.currentSaveId) as Y.Map<unknown>;
  }

  /**
   * 获取当前存档 ID
   */
  getCurrentSaveId(): string | null {
    return this.currentSaveId;
  }

  /**
   * 获取存档类型
   */
  getSaveType(saveId: string): SaveType {
    const saves = this.getSaveSlots();
    const save = saves.get(saveId) as Y.Map<unknown> | undefined;
    if (!save) {
      return "solo"; // 默认返回单人类型
    }
    return (save.get("type") as SaveType) || "solo";
  }

  /**
   * 删除存档
   */
  deleteSave(saveId: string): void {
    const saves = this.getSaveSlots();

    if (!saves.has(saveId)) {
      throw new Error(`[YjsManager] Save not found: ${saveId}`);
    }

    saves.delete(saveId);

    // 如果删除的是当前存档，清空当前存档 ID
    if (this.currentSaveId === saveId) {
      this.currentSaveId = null;
      this.persistCurrentSave();
    }
  }

  /**
   * 更新存档的更新时间
   */
  touchSave(saveId?: string): void {
    const targetSaveId = saveId || this.currentSaveId;
    if (!targetSaveId) return;

    const saves = this.getSaveSlots();
    const save = saves.get(targetSaveId) as Y.Map<unknown>;

    if (save) {
      save.set("updatedAt", Date.now());
    }
  }

  /**
   * 重命名存档
   */
  renameSave(saveId: string, newName: string): void {
    const saves = this.getSaveSlots();
    const save = saves.get(saveId) as Y.Map<unknown>;

    if (!save) {
      throw new Error(`[YjsManager] Save not found: ${saveId}`);
    }

    save.set("name", newName);
    save.set("updatedAt", Date.now());
  }

  /**
   * 导入存档数据
   *
   * 将外部导入的存档数据写入 Yjs，生成新的 ID
   * @param data 导入的存档数据
   * @returns 新生成的存档 ID
   */
  importSave(data: ImportSaveData): string {
    const saves = this.getSaveSlots();
    const saveId = crypto.randomUUID();
    const now = Date.now();

    // 生成 ID 映射
    const conversationIdMap: Record<string, string> = {};
    const messageIdMap: Record<string, string> = {};

    for (const conv of data.conversations) {
      conversationIdMap[conv.id] = crypto.randomUUID();
    }

    for (const messages of Object.values(data.messages)) {
      for (const msg of messages) {
        messageIdMap[msg.id] = crypto.randomUUID();
      }
    }

    // 创建存档 Map
    const saveMap = new Y.Map();
    saveMap.set("id", saveId);
    saveMap.set("name", data.name);
    saveMap.set("createdAt", now);
    saveMap.set("updatedAt", now);

    // 创建会话 Map（值为普通对象，保持与 ChatRepository 结构一致）
    const conversationsMap = new Y.Map();
    for (const conv of data.conversations) {
      const newConvId = conversationIdMap[conv.id];
      const convData = {
        id: newConvId,
        title: conv.title,
        createdAt: conv.createdAt,
        updatedAt: conv.updatedAt,
        ...(conv.metadata ? { metadata: conv.metadata } : {}),
      };
      conversationsMap.set(newConvId, convData);
    }
    saveMap.set("conversations", conversationsMap);

    // 创建消息 Map（值为普通对象，保持与 ChatRepository 结构一致）
    const messagesMap = new Y.Map();
    for (const [oldConvId, messages] of Object.entries(data.messages)) {
      const newConvId = conversationIdMap[oldConvId];
      if (!newConvId) continue;

      const msgArray = new Y.Array();
      for (const msg of messages) {
        const msgData = {
          id: messageIdMap[msg.id],
          role: msg.role,
          content: msg.content,
          createdAt: msg.createdAt,
          ...(msg.updatedAt ? { updatedAt: msg.updatedAt } : {}),
          ...(msg.metadata ? { metadata: msg.metadata } : {}),
        };
        msgArray.push([msgData]);
      }
      messagesMap.set(newConvId, msgArray);
    }
    saveMap.set("messages", messagesMap);

    // 创建游戏状态 Map
    const gameStateMap = new Y.Map();
    for (const [key, value] of Object.entries(data.gameState)) {
      gameStateMap.set(key, value);
    }
    saveMap.set("gameState", gameStateMap);

    // 创建角色 Array（Phase 2 新增）
    if (data.characters && data.characters.length > 0) {
      const charactersArray = new Y.Array();
      for (const char of data.characters) {
        // 角色 ID 保持不变（不需要重新生成，因为角色与玩家身份绑定）
        const charData = {
          id: char.id,
          name: char.name,
          creatorUniqueTag: char.creatorUniqueTag,
          operatorUserId: char.operatorUserId,
          operatorUniqueTag: char.operatorUniqueTag,
          status: char.status,
          createdAt: char.createdAt,
          updatedAt: char.updatedAt,
          ...(char.attributes ? { attributes: char.attributes } : {}),
        };
        charactersArray.push([charData]);
      }
      saveMap.set("characters", charactersArray);
    }

    // 添加到存档槽位
    saves.set(saveId, saveMap);

    return saveId;
  }

  /**
   * 导出存档数据
   *
   * 从 Yjs 提取存档数据，转换为普通 JSON 对象
   * @param saveId 存档 ID
   * @returns 导出的存档数据，如果存档不存在则返回 null
   */
  exportSave(saveId: string): ExportSaveData | null {
    const saves = this.getSaveSlots();
    const saveMap = saves.get(saveId) as Y.Map<unknown> | undefined;

    if (!saveMap) return null;

    // 提取基本信息
    const id = saveMap.get("id") as string;
    const name = (saveMap.get("name") as string) || "未命名存档";
    const createdAt = (saveMap.get("createdAt") as number) || Date.now();
    const updatedAt = (saveMap.get("updatedAt") as number) || Date.now();

    // 提取会话
    const conversationsMap = saveMap.get("conversations") as
      | Y.Map<unknown>
      | undefined;
    const conversations: ExportConversationData[] = [];

    if (conversationsMap) {
      conversationsMap.forEach((conv) => {
        const convObj = conv as Record<string, unknown>;
        conversations.push({
          id: convObj.id as string,
          title: (convObj.title as string) || "未命名会话",
          createdAt: (convObj.createdAt as number) || Date.now(),
          updatedAt: (convObj.updatedAt as number) || Date.now(),
          metadata: (convObj.metadata as Record<string, unknown>) || undefined,
        });
      });
    }

    // 提取消息
    const messagesMap = saveMap.get("messages") as
      | Y.Map<Y.Array<unknown>>
      | undefined;
    const messages: Record<string, ExportMessageData[]> = {};

    if (messagesMap) {
      messagesMap.forEach((msgArray, convId) => {
        if (msgArray instanceof Y.Array) {
          messages[convId] = msgArray.toArray().map((msg) => {
            const msgObj = msg as Record<string, unknown>;
            return {
              id: msgObj.id as string,
              role: msgObj.role as "user" | "assistant" | "system",
              content: (msgObj.content as string) || "",
              createdAt: (msgObj.createdAt as number) || Date.now(),
              updatedAt: msgObj.updatedAt as number | undefined,
              metadata:
                (msgObj.metadata as Record<string, unknown>) || undefined,
            };
          });
        }
      });
    }

    // 提取游戏状态
    const gameStateMap = saveMap.get("gameState") as Y.Map<unknown> | undefined;
    const gameState: Record<string, unknown> = {};

    if (gameStateMap) {
      gameStateMap.forEach((value, key) => {
        // 将 Yjs 类型转换为普通 JSON
        if (value instanceof Y.Map || value instanceof Y.Array) {
          gameState[key] = value.toJSON();
        } else {
          gameState[key] = value;
        }
      });
    }

    // 提取角色数据（Phase 2 新增）
    const charactersArray = saveMap.get("characters") as
      | Y.Array<unknown>
      | undefined;
    const characters: Array<{
      id: string;
      name: string;
      creatorUniqueTag: string;
      operatorUserId: string;
      operatorUniqueTag: string;
      status: "active" | "inactive" | "dead";
      createdAt: number;
      updatedAt: number;
      attributes?: Record<string, unknown>;
    }> = [];

    if (charactersArray) {
      charactersArray.forEach((char) => {
        const charObj = char as Record<string, unknown>;
        characters.push({
          id: charObj.id as string,
          name: (charObj.name as string) || "未命名角色",
          creatorUniqueTag: (charObj.creatorUniqueTag as string) || "",
          operatorUserId: (charObj.operatorUserId as string) || "",
          operatorUniqueTag: (charObj.operatorUniqueTag as string) || "",
          status:
            (charObj.status as "active" | "inactive" | "dead") || "active",
          createdAt: (charObj.createdAt as number) || Date.now(),
          updatedAt: (charObj.updatedAt as number) || Date.now(),
          attributes: charObj.attributes as Record<string, unknown> | undefined,
        });
      });
    }

    return {
      id,
      name,
      createdAt,
      updatedAt,
      conversations,
      messages,
      gameState,
      characters: characters.length > 0 ? characters : undefined,
    };
  }

  /**
   * 更新联机存档的成员信息
   *
   * @param saveId 存档 ID
   * @param members 成员列表
   * @param roomCode 房间码（可选）
   */
  updateSaveMembers(
    saveId: string,
    members: SaveMemberInfo[],
    roomCode?: string
  ): void {
    const saves = this.getSaveSlots();
    const save = saves.get(saveId) as Y.Map<unknown>;

    if (!save) {
      return;
    }

    const saveType = save.get("type") as SaveType;
    if (saveType !== "multiplayer") {
      return;
    }

    save.set("members", members);
    save.set("memberCount", members.length);
    if (roomCode) {
      save.set("lastRoomCode", roomCode);
    }
    save.set("updatedAt", Date.now());
  }

  /**
   * 更新联机存档的房间配置
   *
   * @param saveId 存档 ID
   * @param config 房间配置
   */
  updateSaveRoomConfig(
    saveId: string,
    config: {
      sessionId?: string;
      roomId?: string;
      /** 上次使用的房间 ID（用于消息迁移判断） */
      lastRoomId?: string;
      roomCode?: string;
      maxPlayers?: number;
      turnDuration?: number;
    }
  ): void {
    const saves = this.getSaveSlots();
    const save = saves.get(saveId) as Y.Map<unknown>;

    if (!save) {
      return;
    }

    if (config.sessionId !== undefined) {
      save.set("sessionId", config.sessionId);
    }
    if (config.roomId !== undefined) {
      save.set("roomId", config.roomId);
    }
    if (config.lastRoomId !== undefined) {
      save.set("lastRoomId", config.lastRoomId);
    }
    if (config.roomCode !== undefined) {
      save.set("lastRoomCode", config.roomCode);
    }
    if (config.maxPlayers !== undefined) {
      save.set("maxPlayers", config.maxPlayers);
    }
    if (config.turnDuration !== undefined) {
      save.set("turnDuration", config.turnDuration);
    }
    save.set("updatedAt", Date.now());
  }

  /**
   * 获取存档的房间配置
   *
   * @param saveId 存档 ID
   * @returns 房间配置，如果存档不存在则返回 null
   */
  getSaveRoomConfig(saveId: string): {
    maxPlayers?: number;
    turnDuration?: number;
  } | null {
    const saves = this.getSaveSlots();
    const save = saves.get(saveId) as Y.Map<unknown>;

    if (!save) {
      return null;
    }

    return {
      maxPlayers: save.get("maxPlayers") as number | undefined,
      turnDuration: save.get("turnDuration") as number | undefined,
    };
  }

  /**
   * 销毁 Yjs 文档和 Provider
   */
  destroy(): void {
    if (this.provider) {
      this.provider.destroy();
      this.provider = null;
    }

    if (this.doc) {
      this.doc.destroy();
      this.doc = null;
    }

    this.currentSaveId = null;
    this.initialized = false;
  }

  /**
   * 检查是否已初始化
   */
  isInitialized(): boolean {
    return this.initialized;
  }
}

/**
 * 全局单例
 */
export const yjsManager = new YjsManager();

/**
 * 存储配额监控
 *
 * 提供 IndexedDB 存储使用情况检测和警告功能
 */

/**
 * 存储使用情况
 */
export interface StorageUsage {
  /** 已使用空间（字节） */
  used: number;
  /** 总配额（字节） */
  quota: number;
  /** 使用百分比 (0-100) */
  percentage: number;
  /** 剩余空间（字节） */
  remaining: number;
  /** 是否支持 Storage API */
  supported: boolean;
}

/**
 * 存储警告级别
 */
export type StorageWarningLevel = "normal" | "warning" | "critical" | "full";

/**
 * 警告阈值配置
 */
export interface StorageThresholds {
  /** 警告阈值（百分比） */
  warning: number;
  /** 严重警告阈值（百分比） */
  critical: number;
}

/**
 * 默认阈值
 */
const DEFAULT_THRESHOLDS: StorageThresholds = {
  warning: 70, // 70% 时警告
  critical: 90, // 90% 时严重警告
};

/**
 * 获取存储使用情况
 * 使用 Storage API（如果可用）
 */
export async function getStorageUsage(): Promise<StorageUsage> {
  // 检查 Storage API 是否可用
  if (!navigator.storage || !navigator.storage.estimate) {
    return {
      used: 0,
      quota: 0,
      percentage: 0,
      remaining: 0,
      supported: false,
    };
  }

  try {
    const estimate = await navigator.storage.estimate();
    const used = estimate.usage || 0;
    const quota = estimate.quota || 0;
    const percentage = quota > 0 ? Math.round((used / quota) * 100) : 0;
    const remaining = quota - used;

    return {
      used,
      quota,
      percentage,
      remaining,
      supported: true,
    };
  } catch {
    return {
      used: 0,
      quota: 0,
      percentage: 0,
      remaining: 0,
      supported: false,
    };
  }
}

/**
 * 获取存储警告级别
 */
export function getStorageWarningLevel(
  usage: StorageUsage,
  thresholds: StorageThresholds = DEFAULT_THRESHOLDS
): StorageWarningLevel {
  if (!usage.supported) {
    return "normal"; // 无法检测时不警告
  }

  if (usage.percentage >= 100) {
    return "full";
  }

  if (usage.percentage >= thresholds.critical) {
    return "critical";
  }

  if (usage.percentage >= thresholds.warning) {
    return "warning";
  }

  return "normal";
}

/**
 * 格式化字节大小为人类可读格式
 */
export function formatBytes(bytes: number): string {
  if (bytes === 0) return "0 B";

  const units = ["B", "KB", "MB", "GB", "TB"];
  const k = 1024;
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  const size = bytes / Math.pow(k, i);

  return `${size.toFixed(i > 0 ? 1 : 0)} ${units[i]}`;
}

/**
 * 获取警告消息
 */
export function getStorageWarningMessage(
  level: StorageWarningLevel,
  usage: StorageUsage
): string | null {
  switch (level) {
    case "full":
      return `存储空间已满！已使用 ${formatBytes(
        usage.used
      )}，无法保存更多数据。请删除不需要的存档。`;
    case "critical":
      return `存储空间严重不足！已使用 ${usage.percentage}%（${formatBytes(
        usage.used
      )} / ${formatBytes(usage.quota)}），剩余 ${formatBytes(
        usage.remaining
      )}。`;
    case "warning":
      return `存储空间不足，已使用 ${usage.percentage}%（${formatBytes(
        usage.used
      )} / ${formatBytes(usage.quota)}）。`;
    case "normal":
    default:
      return null;
  }
}

/**
 * 检查存储并返回警告信息（如果需要）
 */
export async function checkStorageAndWarn(
  thresholds?: StorageThresholds
): Promise<{
  usage: StorageUsage;
  level: StorageWarningLevel;
  message: string | null;
}> {
  const usage = await getStorageUsage();
  const level = getStorageWarningLevel(usage, thresholds);
  const message = getStorageWarningMessage(level, usage);

  return { usage, level, message };
}

/**
 * 请求持久化存储
 * 防止浏览器在存储压力下自动清除数据
 */
export async function requestPersistentStorage(): Promise<boolean> {
  if (!navigator.storage || !navigator.storage.persist) {
    return false;
  }

  try {
    // 检查是否已经是持久化存储
    const isPersisted = await navigator.storage.persisted();
    if (isPersisted) {
      return true;
    }

    // 请求持久化
    const granted = await navigator.storage.persist();
    return granted;
  } catch (_error) {
    return false;
  }
}

/**
 * 检查是否为持久化存储
 */
export async function isPersistentStorage(): Promise<boolean> {
  if (!navigator.storage || !navigator.storage.persisted) {
    return false;
  }

  try {
    return await navigator.storage.persisted();
  } catch {
    return false;
  }
}

import "@/styles/globals.css";
import { enableMapSet } from "immer";
import React, { useState } from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import {
  initYjs,
  showIndexedDBError,
  StorageErrorDialog,
  yjsManager,
  type StorageErrorType,
} from "./core/yjs";
import { YjsTestPage } from "./core/yjs/test-page";
import { registerAllModules } from "./modules";

// 启用 Immer 的 Map/Set 支持
enableMapSet();

/**
 * 错误页面组件
 * 当 Yjs 初始化失败时显示
 */
function ErrorPage({
  errorType,
  onRetry,
}: {
  errorType: StorageErrorType;
  onRetry: () => void;
}) {
  const [open, setOpen] = useState(true);

  return (
    <div className="dark min-h-screen bg-black flex items-center justify-center">
      <StorageErrorDialog
        open={open}
        errorType={errorType}
        onRetry={onRetry}
        onDismiss={() => setOpen(false)}
      />
      {/* 背景提示 */}
      {!open && (
        <div className="text-center text-gray-500">
          <p className="text-lg mb-4">游戏无法启动</p>
          <button
            onClick={() => setOpen(true)}
            className="text-cyan-400 hover:text-cyan-300 underline"
          >
            查看详情
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * 渲染错误页面
 */
function renderErrorPage(errorType: StorageErrorType, onRetry: () => void) {
  const root = document.getElementById("root");
  if (!root) return;

  ReactDOM.createRoot(root).render(
    <React.StrictMode>
      <ErrorPage errorType={errorType} onRetry={onRetry} />
    </React.StrictMode>
  );
}

/**
 * 渲染主应用
 */
function renderApp(isTestMode: boolean) {
  const root = document.getElementById("root");
  if (!root) return;

  ReactDOM.createRoot(root).render(
    <React.StrictMode>
      {isTestMode ? <YjsTestPage /> : <App />}
    </React.StrictMode>
  );

  // Test mode logging removed for production
}

// 初始化应用
async function bootstrap() {
  // 1. 初始化 Yjs（包含 IndexedDB 可用性检查）
  const initResult = await initYjs();

  if (!initResult.success) {
    // 尝试使用 React 渲染错误页面
    try {
      renderErrorPage(initResult.errorType!, () => {
        // 重试：刷新页面
        window.location.reload();
      });
    } catch {
      // 降级：使用 alert
      showIndexedDBError(initResult.errorType);
    }
    return;
  }

  // 2. 挂载全局 API（方便控制台测试）
  if (typeof window !== "undefined") {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (window as any).yjsManager = yjsManager;
  }

  // 3. 注册所有模块（命令处理器、事件处理器等）
  await registerAllModules();

  // 4. 检查是否为测试模式
  const isTestMode =
    new URLSearchParams(window.location.search).get("test") === "yjs";

  // 5. 渲染应用或测试页面
  renderApp(isTestMode);
}

bootstrap().catch(() => {
  // Bootstrap failed silently
});

/**
 * Chat 命令处理器
 *
 * 重构说明：
 * - 业务数据操作通过 ChatRepository（Yjs 持久化）
 * - UI 临时状态通过 useChatUIStore（内存）
 * - Repository 操作会自动发布领域事件
 * - AI 调用通过 AiExecutor 统一处理（支持重试、取消）
 */

import { eventBus } from "@/core";
import type {
  Command,
  CommandContext,
  CommandHandler,
  CommandResult,
} from "@/core/command-bus";
import type {
  ClearConversationPayload,
  CreateConversationPayload,
  DeleteConversationPayload,
  DeleteMessagePayload,
  SelectConversationPayload,
  SendMessagePayload,
} from "@/domain/commands/chat";
import { ChatCommands } from "@/domain/commands/chat";
import { createConversation } from "@/domain/entities/conversation";
import { createMessage } from "@/domain/entities/message";
import { ChatEvents } from "@/domain/events/chat";
import { createAiExecutor } from "@/lib/ai/executor";
import { useSettingsStore } from "@/stores/settings";
import { getChatRepository } from "../repository/factory";
import { useChatUIStore } from "../store/ui-store";

/**
 * 发送消息处理器
 *
 * 数据流：
 * 1. 通过 Repository 添加用户消息（自动持久化到 Yjs + 发布事件）
 * 2. 如果是用户消息，创建 AI 响应消息
 * 3. 流式更新 AI 响应内容
 * 4. UI 状态（loading, streamingMessageId）通过 useChatUIStore 管理
 */
const sendMessageHandler: CommandHandler<SendMessagePayload, void> = async (
  command: Command<SendMessagePayload>,
  context: CommandContext
): Promise<CommandResult<void>> => {
  const { content, conversationId, role = "user" } = command.payload;
  const uiStore = useChatUIStore.getState();
  const aiConfig = useSettingsStore.getState().aiConfig;

  try {
    // 获取 Repository 实例
    const repository = getChatRepository();

    // 1. 创建用户消息
    const userMessage = createMessage({
      role,
      content,
      conversationId,
    });

    // ✅ 通过 Repository 添加（自动持久化 + 发布事件）
    repository.addMessage(conversationId, userMessage);

    // 如果是 user 消息，需要触发 AI 响应
    if (role === "user") {
      // 2. 创建 AI 响应消息（初始为空）
      const assistantMessage = createMessage({
        role: "assistant",
        content: "",
        conversationId,
      });

      // ✅ 通过 Repository 添加
      repository.addMessage(conversationId, assistantMessage);

      // UI 临时状态
      uiStore.setStreamingMessageId(assistantMessage.id);
      uiStore.setLoading(true);

      eventBus.emit(
        eventBus.createEvent(ChatEvents.STREAM_START, {
          messageId: assistantMessage.id,
          conversationId,
        }),
        { correlationId: context.commandId }
      );

      // 3. 使用 AiExecutor 调用 AI API（支持重试和取消）
      // ✅ 从 Repository 获取消息历史
      const messages = repository.getMessages(conversationId).map((m) => ({
        role: m.role as "system" | "user" | "assistant",
        content: m.content,
      }));

      // 创建执行器
      const executor = createAiExecutor(aiConfig);

      // 执行 AI 调用
      const result = await executor.execute({
        messages,
        onChunk: (chunk) => {
          // 获取当前消息并追加 chunk
          const currentMessage = repository
            .getMessages(conversationId)
            .find((m) => m.id === assistantMessage.id);
          const currentContent = currentMessage?.content ?? "";

          // ✅ 通过 Repository 更新消息内容
          repository.updateMessage(conversationId, assistantMessage.id, {
            content: currentContent + chunk,
            status: "streaming",
          });

          eventBus.emit(
            eventBus.createEvent(ChatEvents.STREAM_CHUNK, {
              messageId: assistantMessage.id,
              chunk,
            }),
            { correlationId: context.commandId }
          );
        },
        onComplete: (finalContent) => {
          // 4. 完成流式响应
          repository.updateMessage(conversationId, assistantMessage.id, {
            content: finalContent,
            status: "complete",
          });

          eventBus.emit(
            eventBus.createEvent(ChatEvents.STREAM_END, {
              messageId: assistantMessage.id,
              finalContent,
            }),
            { correlationId: context.commandId }
          );
        },
        onRetry: (attempt, maxAttempts, error) => {
          // 通知重试状态
          eventBus.emit(
            eventBus.createEvent(ChatEvents.STREAM_ERROR, {
              messageId: assistantMessage.id,
              error: `正在重试 (${attempt}/${maxAttempts})...`,
            }),
            { correlationId: context.commandId }
          );
        },
      });

      // UI 临时状态重置
      uiStore.setStreamingMessageId(null);
      uiStore.setLoading(false);

      // 处理执行结果
      if (!result.success) {
        const errorMessage = result.error?.message ?? "Unknown error";

        // ✅ 通过 Repository 更新错误状态
        repository.updateMessage(conversationId, assistantMessage.id, {
          status: "error",
          error: errorMessage,
        });

        eventBus.emit(
          eventBus.createEvent(ChatEvents.STREAM_ERROR, {
            messageId: assistantMessage.id,
            error: errorMessage,
          }),
          { correlationId: context.commandId }
        );

        return { success: false, error: errorMessage };
      }
    }

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Failed to send message",
    };
  }
};

/**
 * 删除消息处理器
 *
 * ✅ 通过 Repository 删除（自动发布事件）
 */
const deleteMessageHandler: CommandHandler<DeleteMessagePayload, void> = async (
  command: Command<DeleteMessagePayload>,
  _context: CommandContext
): Promise<CommandResult<void>> => {
  const { messageId, conversationId } = command.payload;

  try {
    const repository = getChatRepository();
    // ✅ Repository.deleteMessage 会自动发布 MESSAGE_DELETED 事件
    repository.deleteMessage(conversationId, messageId);
    return { success: true };
  } catch (error) {
    return {
      success: false,
      error:
        error instanceof Error ? error.message : "Failed to delete message",
    };
  }
};

/**
 * 创建会话处理器
 *
 * ✅ 通过 Repository 创建（自动发布事件）
 */
const createConversationHandler: CommandHandler<
  CreateConversationPayload,
  string
> = async (
  command: Command<CreateConversationPayload>,
  _context: CommandContext
): Promise<CommandResult<string>> => {
  try {
    const repository = getChatRepository();
    const uiStore = useChatUIStore.getState();

    const conversation = createConversation(command.payload);

    // ✅ Repository.addConversation 会自动发布 CONVERSATION_CREATED 事件
    repository.addConversation(conversation);

    // 设置为当前会话（UI 状态）
    uiStore.setCurrentConversation(conversation.id);

    return { success: true, data: conversation.id };
  } catch (error) {
    return {
      success: false,
      error:
        error instanceof Error
          ? error.message
          : "Failed to create conversation",
    };
  }
};

/**
 * 选择会话处理器
 *
 * 只更新 UI 状态，不涉及 Repository
 */
const selectConversationHandler: CommandHandler<
  SelectConversationPayload,
  void
> = async (
  command: Command<SelectConversationPayload>,
  context: CommandContext
): Promise<CommandResult<void>> => {
  const uiStore = useChatUIStore.getState();
  uiStore.setCurrentConversation(command.payload.conversationId);

  eventBus.emit(
    eventBus.createEvent(ChatEvents.CONVERSATION_SELECTED, {
      conversationId: command.payload.conversationId,
    }),
    { correlationId: context.commandId }
  );

  return { success: true };
};

/**
 * 清空会话处理器
 *
 * ✅ 通过 Repository 清空消息
 */
const clearConversationHandler: CommandHandler<
  ClearConversationPayload,
  void
> = async (
  command: Command<ClearConversationPayload>,
  _context: CommandContext
): Promise<CommandResult<void>> => {
  try {
    const repository = getChatRepository();
    repository.clearMessages(command.payload.conversationId);
    return { success: true };
  } catch (error) {
    return {
      success: false,
      error:
        error instanceof Error ? error.message : "Failed to clear conversation",
    };
  }
};

/**
 * 删除会话处理器
 *
 * ✅ 通过 Repository 删除（自动发布事件）
 */
const deleteConversationHandler: CommandHandler<
  DeleteConversationPayload,
  void
> = async (
  command: Command<DeleteConversationPayload>,
  _context: CommandContext
): Promise<CommandResult<void>> => {
  const { conversationId } = command.payload;

  try {
    const repository = getChatRepository();
    const uiStore = useChatUIStore.getState();

    // ✅ Repository.deleteConversation 会自动发布 CONVERSATION_DELETED 事件
    repository.deleteConversation(conversationId);

    // 如果删除的是当前会话，清空选择
    if (uiStore.currentConversationId === conversationId) {
      uiStore.setCurrentConversation(null);
    }

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error:
        error instanceof Error
          ? error.message
          : "Failed to delete conversation",
    };
  }
};

/**
 * 创建所有命令处理器
 */
export function createChatCommandHandlers(): Record<
  string,
  CommandHandler<unknown, unknown>
> {
  return {
    [ChatCommands.SEND_MESSAGE]: sendMessageHandler as CommandHandler<
      unknown,
      unknown
    >,
    [ChatCommands.DELETE_MESSAGE]: deleteMessageHandler as CommandHandler<
      unknown,
      unknown
    >,
    [ChatCommands.CREATE_CONVERSATION]:
      createConversationHandler as CommandHandler<unknown, unknown>,
    [ChatCommands.SELECT_CONVERSATION]:
      selectConversationHandler as CommandHandler<unknown, unknown>,
    [ChatCommands.CLEAR_CONVERSATION]:
      clearConversationHandler as CommandHandler<unknown, unknown>,
    [ChatCommands.DELETE_CONVERSATION]:
      deleteConversationHandler as CommandHandler<unknown, unknown>,
  };
}

/**
 * Chat 模块入口
 *
 * 职责：
