/**
 * 房间命令处理器
 *
 * 遵循 DDD + CommandBus 架构：
 * - 所有状态修改都在这里进行
 * - 状态型事件由 SyncBridge 统一派生（基于 Yjs 状态变化）
 * - 意图型事件通过 EventMeta 传递上下文
 * - 本地业务事件仍由 Handler 直接发布
 * - 集成 API 调用和 MultiplayerProvider
 *
 * ⚠️ 架构说明（SyncBridge 改造后）：
 * - Handler 负责状态变更，不直接 emit 可由 SyncBridge 派生的事件
 * - SyncBridge 派生的事件：GAME_STARTED, GAME_ENDED, TURN_STARTED,
 *   MEMBER_JOINED, MEMBER_LEFT/KICKED, HOST_TRANSFERRED, PHASE_ENTERED
 * - Handler 保留的事件：ROOM_CREATED, ACTION_SUBMITTED, ACTION_LOCKED,
 *   PHASE_COMPLETED, PHASE_ADVANCED, TURN_COMPLETED, TURN_DEADLINE_EXTENDED
 *
 * @see plans/room-sync-bridge-proposal.md
 */

import { getMultiplayerConfig } from "@/config/multiplayer";
import type { CommandContext, CommandResult } from "@/core/command-bus";
import { eventBus } from "@/core/event-bus";
import type { Member, SaveMemberInfo } from "@/core/yjs";
import {
  apiClient,
  ApiError,
  historyDocProvider,
  multiplayerProvider,
  subdocManager,
  turnDocProvider,
  yjsManager,
} from "@/core/yjs";
import { generateRoomCode } from "@/core/yjs/subdoc-manager";
import type {
  CompleteTurnPayload,
  CreateRoomPayload,
  JoinRoomPayload,
  LeaveRoomPayload,
  QueryRoomPayload,
  QueryRoomResult,
  StartTurnPayload,
  SubmitActionPayload,
  TransferHostPayload,
} from "@/domain/commands/room";
import {
  RoomEvents,
  type ActionSubmittedEvent,
  type RoomCreatedEvent,
  type TurnCompletedEvent,
} from "@/domain/events/room";
import { SaveEvents } from "@/domain/events/save";
import { getUniqueTag } from "@/lib/user-identity";
import * as Y from "yjs";
import { useRoomStore } from "../store";
import type { HostTransferMeta, MemberActionMeta } from "../sync/types";

// ===== 常量 =====

/** 房间码冲突时的最大重试次数 */
const MAX_CODE_RETRY = 3;

// ===== EventMeta 写入辅助函数 =====

/**
 * 写入成员事件元数据
 *
 * 用于意图型事件（如 MEMBER_KICKED），在状态变更前记录意图信息，
 * 供 SyncBridge 派生正确的事件类型。
 *
 * @param roomId 房间 ID
 * @param userId 用户 ID
 * @param meta 元数据
 */
function writeMemberActionMeta(
  roomId: string,
  userId: string,
  meta: MemberActionMeta
): void {
  const mainDoc = subdocManager.getMainDoc(roomId);
  if (!mainDoc) {
    console.warn(
      `[RoomHandler] Cannot write member action meta: MainDoc not found for ${roomId}`
    );
    return;
  }

  mainDoc.transact(() => {
    const eventMetaMap = mainDoc.getMap("eventMeta");

    // 确保 memberActions Map 存在
    let memberActionsMap = eventMetaMap.get("memberActions") as
      | Y.Map<MemberActionMeta>
      | undefined;
    if (!memberActionsMap) {
      memberActionsMap = new Y.Map<MemberActionMeta>();
      eventMetaMap.set("memberActions", memberActionsMap);
    }

    memberActionsMap.set(userId, meta);
  });
}

/**
 * 写入 Host 转让元数据
 *
 * 用于区分主动转让和自动转让，供 SyncBridge 派生正确的事件类型。
 *
 * @param roomId 房间 ID
 * @param meta 元数据
 */
function writeHostTransferMeta(roomId: string, meta: HostTransferMeta): void {
  const mainDoc = subdocManager.getMainDoc(roomId);
  if (!mainDoc) {
    console.warn(
      `[RoomHandler] Cannot write host transfer meta: MainDoc not found for ${roomId}`
    );
    return;
  }

  mainDoc.transact(() => {
    const eventMetaMap = mainDoc.getMap("eventMeta");
    eventMetaMap.set("hostTransfer", meta);
  });
}

// ===== 创建房间 =====

/**
 * 创建房间命令处理器
 *
 * 流程：
 * 1. 生成 roomId 和 code
 * 2. 调用 API 注册房间（冲突时自动重试）
 * 3. 获取 Token
 * 4. 创建本地 Yjs 文档
 * 5. 连接 WebSocket
 * 6. 发布事件（触发 Store 更新）
 */
export async function createRoomHandler(
  payload: CreateRoomPayload,
  _context: CommandContext
): Promise<CommandResult<{ roomId: string; code: string }>> {
  const roomId = crypto.randomUUID();
  const now = Date.now();
  let code: string = "";
  let retryCount = 0;

  // 确保 API 客户端已配置
  const config = getMultiplayerConfig();
  if (!apiClient.getBaseUrl()) {
    apiClient.setBaseUrl(config.apiUrl);
  }

  try {
    // 步骤 1: 注册房间到服务器（带重试）
    while (retryCount < MAX_CODE_RETRY) {
      code = generateRoomCode();

      try {
        await apiClient.registerRoom({
          roomId,
          code,
          hostUserId: payload.hostUserId,
          hostDisplayName: payload.hostDisplayName,
          name: payload.name,
          maxPlayers: payload.maxPlayers,
        });
        break;
      } catch (error) {
        if (error instanceof ApiError && error.status === 409) {
          // 房间码冲突，重试
          retryCount++;
          if (retryCount >= MAX_CODE_RETRY) {
            return {
              success: false,
              error: "无法生成唯一房间码，请稍后重试",
            };
          }
        } else {
          throw error;
        }
      }
    }

    // 步骤 2: 获取 Token
    const tokenResponse = await apiClient.getToken({
      userId: payload.hostUserId,
      roomId,
      role: "host",
    });

    // 步骤 3: 准备 saveId（核心匹配字段）
    // 续玩时使用现有存档的 id，新建时后续创建存档时生成
    // saveId 将在步骤 6 处理存档后写入 MainDoc
    let saveId: string | undefined;
    if (payload.fromSaveId) {
      // 续玩场景：使用现有存档的 id 作为 saveId
      saveId = payload.fromSaveId;
    }
    // 新建场景：saveId 将在创建存档后获取

    // 步骤 4: 创建本地 Yjs 文档
    // 注意：saveId 将在步骤 6 处理存档后写入
    const { mainDoc } = subdocManager.createMainDoc(roomId, {
      name: payload.name,
      hostUserId: payload.hostUserId,
      maxPlayers: payload.maxPlayers,
      turnDuration: payload.turnDuration,
      saveId, // 续玩时传入，新建时为 undefined
    });

    // 更新 mainDoc 的 code（因为 createMainDoc 会生成新的 code，我们需要用服务器确认的 code）
    const metadataMap = mainDoc.getMap("metadata");
    metadataMap.set("code", code);

    // 添加房主作为第一个成员
    const membersMap = mainDoc.getMap("members") as Y.Map<Member>;
    const hostMember: Member = {
      userId: payload.hostUserId,
      displayName: payload.hostDisplayName,
      role: "host",
      joinedAt: now,
      lastActiveAt: now,
      status: "online",
    };
    membersMap.set(payload.hostUserId, hostMember);

    // 步骤 4: 连接 WebSocket
    await multiplayerProvider.connect(
      {
        roomId,
        userId: payload.hostUserId,
        displayName: payload.hostDisplayName,
        role: "host",
        token: tokenResponse.token,
        tokenExpiresAt: tokenResponse.expiresAt,
        wsUrl: config.wsUrl,
        onTokenRefresh: async () => {
          // Token 刷新回调
          return apiClient.getToken({
            userId: payload.hostUserId,
            roomId,
            role: "host",
          });
        },
      },
      mainDoc
    );

    // 连接 HistoryDoc（复用 MainDoc 的 WebSocket）
    const mpConfig = multiplayerProvider.getConfig();
    if (mpConfig) {
      historyDocProvider.setConfig({
        roomId: mpConfig.roomId,
        token: mpConfig.token,
        wsUrl: mpConfig.wsUrl,
      });
      const historyDoc = await subdocManager.loadHistoryDoc(roomId);
      await historyDocProvider.connect(roomId, historyDoc);
      try {
        await historyDocProvider.waitForSync(roomId, 10000);
      } catch (_syncError) {
        // HistoryDoc 同步超时，继续执行
      }
    }

    // 步骤 5: 设置 localUser（确保事件处理能正确识别当前用户）
    useRoomStore.getState().setLocalUser({
      userId: payload.hostUserId,
      displayName: payload.hostDisplayName,
    });

    // 步骤 6: 处理存档
    // saveId 在步骤 3 已初始化（续玩场景）或在此处创建（新建场景）

    if (payload.fromSaveId) {
      // 从现有存档创建房间（联机续玩场景）
      // 存档已在 App.tsx 的 handleStartNewParty 中加载
      // saveId 已在步骤 3 设置为 payload.fromSaveId

      // 读取存档的 currentTurnNumber 并恢复到 MainDoc
      const saveSlot = yjsManager.getSaveSlots().get(saveId!) as
        | Y.Map<unknown>
        | undefined;
      if (saveSlot) {
        const savedTurnNumber =
          (saveSlot.get("currentTurnNumber") as number) || 0;
        if (savedTurnNumber > 0) {
          const configMap = mainDoc.getMap("config");
          configMap.set("currentTurnNumber", savedTurnNumber);
        }

        // === 消息迁移：使用 lastRoomId 判断是否需要迁移 ===
        // 续玩时 roomId 会变化，需要将旧的消息迁移到新的 conversationId 下
        const lastRoomId = saveSlot.get("lastRoomId") as string | undefined;
        // 兼容旧存档：如果没有 lastRoomId，回退到 roomId
        const oldRoomId =
          lastRoomId || (saveSlot.get("roomId") as string | undefined);

        if (oldRoomId && oldRoomId !== roomId) {
          const oldConversationId = `room:${oldRoomId}:main`;
          const newConversationId = `room:${roomId}:main`;

          const messagesMap = saveSlot.get("messages") as
            | Y.Map<Y.Array<unknown>>
            | undefined;

          if (messagesMap) {
            const oldMessages = messagesMap.get(oldConversationId) as
              | Y.Array<unknown>
              | undefined;

            if (oldMessages && oldMessages.length > 0) {
              const messageCount = oldMessages.length;

              // 使用 Yjs 事务批量操作，避免多次触发变更检测
              const rootDoc = yjsManager.getDoc();
              if (rootDoc) {
                rootDoc.transact(() => {
                  // 创建新的消息数组
                  let newMessages = messagesMap.get(newConversationId) as
                    | Y.Array<unknown>
                    | undefined;
                  if (!newMessages) {
                    newMessages = new Y.Array<unknown>();
                    messagesMap.set(newConversationId, newMessages);
                  }

                  // 批量迁移消息：使用 insert 一次性插入所有消息
                  // 避免逐条 push 导致的性能问题
                  const migratedMessages: unknown[] = [];
                  for (let i = 0; i < messageCount; i++) {
                    const msg = oldMessages.get(i) as Record<string, unknown>;
                    migratedMessages.push({
                      ...msg,
                      conversationId: newConversationId,
                    });
                  }

                  // 一次性插入所有消息
                  newMessages.insert(newMessages.length, migratedMessages);

                  // 删除旧的消息数组（节省空间，避免重复）
                  messagesMap.delete(oldConversationId);
                });
              }
            }
          }

          // archivedTurns 不需要迁移，因为它不依赖 conversationId
        }

        // === 角色恢复：从 SaveSlot 恢复 characters 到 MainDoc ===
        const savedCharacters = saveSlot.get("characters") as
          | Y.Array<unknown>
          | undefined;

        if (savedCharacters && savedCharacters.length > 0) {
          const charactersMap = mainDoc.getMap("characters") as Y.Map<
            Y.Map<unknown>
          >;

          // 使用 Yjs 事务批量操作
          const rootDoc = yjsManager.getDoc();
          if (rootDoc) {
            rootDoc.transact(() => {
              for (let i = 0; i < savedCharacters.length; i++) {
                const charData = savedCharacters.get(i) as Record<
                  string,
                  unknown
                >;
                const characterId = charData.id as string;

                // 检查是否已存在（避免重复添加）
                if (!charactersMap.has(characterId)) {
                  // 创建嵌套 Y.Map 存储角色数据
                  const charMap = new Y.Map<unknown>();
                  charMap.set("id", charData.id);
                  charMap.set("name", charData.name);
                  charMap.set("creatorUniqueTag", charData.creatorUniqueTag);
                  charMap.set("operatorUserId", charData.operatorUserId);
                  charMap.set("operatorUniqueTag", charData.operatorUniqueTag);
                  charMap.set("status", charData.status || "active");
                  charMap.set("createdAt", charData.createdAt);
                  charMap.set("updatedAt", charData.updatedAt);
                  if (charData.attributes) {
                    charMap.set("attributes", charData.attributes);
                  }

                  charactersMap.set(characterId, charMap);
                }
              }
            });
          }
        }
      }

      // 更新存档的房间信息（包括 lastRoomId）
      yjsManager.updateSaveRoomConfig(saveId!, {
        roomId,
        lastRoomId: roomId, // 更新 lastRoomId 为当前 roomId
        roomCode: code,
        maxPlayers: payload.maxPlayers ?? 8,
        turnDuration: payload.turnDuration ?? 5 * 60 * 1000,
      });
    } else {
      // 创建新的联机存档
      const hostMemberInfo: SaveMemberInfo = {
        displayName: payload.hostDisplayName,
        role: "host",
      };

      // 创建存档并获取 saveId
      saveId = yjsManager.createSave({
        name: payload.name || `联机存档 ${code}`,
        type: "multiplayer",
        roomId,
        roomCode: code,
        members: [hostMemberInfo],
      });

      // 将 saveId 写入 MainDoc（新建场景）
      const configMap = mainDoc.getMap("config");
      configMap.set("saveId", saveId);

      // 保存房间配置到存档（包括 lastRoomId）
      yjsManager.updateSaveRoomConfig(saveId, {
        lastRoomId: roomId, // 设置初始 lastRoomId
        maxPlayers: payload.maxPlayers ?? 8,
        turnDuration: payload.turnDuration ?? 5 * 60 * 1000,
      });

      // 加载新创建的存档
      yjsManager.loadSave(saveId);

      // 发布 SAVE_CREATED 事件（通知 Chat 模块初始化会话）
      const saveName = payload.name || `联机存档 ${code}`;
      eventBus.emit(
        eventBus.createEvent(SaveEvents.SAVE_CREATED, {
          saveId,
          name: saveName,
        })
      );
    }

    // 步骤 7: 发布 ROOM_CREATED 事件（本地业务事件，不由 SyncBridge 派生）
    // 这个事件用于通知 UI 房间创建成功，包含房间码等信息
    const event: RoomCreatedEvent = {
      roomId,
      code,
      name: payload.name,
      hostUserId: payload.hostUserId,
      hostDisplayName: payload.hostDisplayName,
      maxPlayers: payload.maxPlayers ?? 8,
      turnDuration: payload.turnDuration ?? 5 * 60 * 1000,
      createdAt: now,
    };
    eventBus.emit(eventBus.createEvent(RoomEvents.ROOM_CREATED, event));

    // ⚠️ SyncBridge 改造：移除 MEMBER_JOINED 和 CONNECTED 事件的 emit
    // 这些事件将由 SyncBridge 通过 Yjs 状态变化自动派生
    // - MEMBER_JOINED: 由 members Map 变化触发
    // - CONNECTED: 由 MultiplayerProvider 状态回调触发（保留在 index.ts）

    return { success: true, data: { roomId, code } };
  } catch (error) {
    // 清理：如果部分创建成功，需要清理
    if (subdocManager.getMainDoc(roomId)) {
      subdocManager.leaveRoom(roomId);
    }
    multiplayerProvider.disconnect();

    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 加入房间 =====

/**
 * 加入房间命令处理器
 *
 * 流程：
 * 1. 调用 API 查询房间
 * 2. 调用 API 添加成员
 * 3. 获取 Token
 * 4. 加载/创建本地 Yjs 文档
 * 5. 连接 WebSocket
 * 6. 发布事件（触发 Store 更新）
 */
export async function joinRoomHandler(
  payload: JoinRoomPayload,
  _context: CommandContext
): Promise<CommandResult<{ roomId: string; isHost: boolean }>> {
  const { code, userId, displayName } = payload;
  const now = Date.now();

  // 确保 API 客户端已配置
  const config = getMultiplayerConfig();
  if (!apiClient.getBaseUrl()) {
    apiClient.setBaseUrl(config.apiUrl);
  }

  try {
    // 步骤 1: 调用 API 查询房间
    let roomId: string;
    try {
      const queryResponse = await apiClient.queryRoom(code);
      roomId = queryResponse.roomId;
    } catch (error) {
      if (error instanceof ApiError && error.status === 404) {
        return { success: false, error: "房间不存在或已过期" };
      }
      throw error;
    }

    // 步骤 2: 调用 API 添加成员
    try {
      await apiClient.addMember({
        roomId,
        userId,
        displayName,
      });
    } catch (error) {
      // 如果已经是成员，继续流程
      if (!(error instanceof ApiError && error.status === 409)) {
        throw error;
      }
    }

    // 步骤 3: 获取 Token
    const tokenResponse = await apiClient.getToken({
      userId,
      roomId,
      role: "guest",
    });

    // 步骤 4: 加载或创建本地 Yjs 文档
    // 首先检查本地是否有房间引用
    let mainDoc: Y.Doc;
    const localRoomRef = subdocManager.findRoomByCode(code);

    if (localRoomRef) {
      // 本地已有房间引用，加载 MainDoc
      mainDoc = await subdocManager.loadMainDoc(roomId);
    } else {
      // 本地没有房间引用，需要从服务器同步
      // 创建一个空的 MainDoc，不设置任何默认值
      // 这样可以避免覆盖服务器端的房间设置（如 maxPlayers）
      mainDoc = subdocManager.createEmptyMainDoc(roomId);
    }

    // 步骤 5: 连接 WebSocket（先连接，让 Yjs 同步数据）
    // 加入房间的用户默认是 guest（isHost 在同步后确定）
    await multiplayerProvider.connect(
      {
        roomId,
        userId,
        displayName,
        role: "guest", // 加入时默认是 guest
        token: tokenResponse.token,
        tokenExpiresAt: tokenResponse.expiresAt,
        wsUrl: config.wsUrl,
        onTokenRefresh: async () => {
          return apiClient.getToken({
            userId,
            roomId,
            role: "guest",
          });
        },
      },
      mainDoc
    );

    // 设置 localUser（确保事件处理能正确识别当前用户）
    const store = useRoomStore.getState();
    store.setLocalUser({
      userId,
      displayName,
    });

    // ⚠️ 关键修改：使用 waitForSync 替代硬编码的 500ms 等待
    // 确保 MainDoc 数据同步完成后再进行后续操作
    try {
      await multiplayerProvider.waitForSync(10000);
    } catch (_syncError) {
      // MainDoc 同步超时，继续执行
    }

    // 连接 HistoryDoc（复用 MainDoc 的 WebSocket）
    const mpConfig = multiplayerProvider.getConfig();
    if (mpConfig) {
      historyDocProvider.setConfig({
        roomId: mpConfig.roomId,
        token: mpConfig.token,
        wsUrl: mpConfig.wsUrl,
      });
      const historyDoc = await subdocManager.loadHistoryDoc(roomId);
      await historyDocProvider.connect(roomId, historyDoc);
      try {
        await historyDocProvider.waitForSync(roomId, 10000);
      } catch (_syncError) {
        // HistoryDoc 同步超时，继续执行
      }
    }

    // 获取成员信息（同步后应该能看到其他成员）
    const membersMap = mainDoc.getMap("members") as Y.Map<Member>;
    const existingMember = membersMap.get(userId);
    const isHost = existingMember?.role === "host";

    // 如果是新成员，添加到文档
    if (!existingMember) {
      const newMember: Member = {
        userId,
        displayName,
        role: "guest",
        joinedAt: now,
        lastActiveAt: now,
        status: "online",
      };
      membersMap.set(userId, newMember);
    } else {
      // 更新在线状态
      const updatedMember: Member = {
        ...existingMember,
        status: "online",
        lastActiveAt: now,
      };
      membersMap.set(userId, updatedMember);
    }

    // 从 mainDoc 获取房间信息（同步后应该有正确的值）
    const metadataMap = mainDoc.getMap("metadata");
    const roomName = (metadataMap.get("name") as string) || `Room ${code}`;
    const maxPlayers = (metadataMap.get("maxPlayers") as number) || 8;
    const turnDuration =
      (metadataMap.get("turnDuration") as number) || 5 * 60 * 1000;

    // 直接设置 currentRoom（避免事件处理中信息丢失）
    store.setCurrentRoom({
      roomId,
      code,
      name: roomName,
      isHost,
      maxPlayers,
      turnDuration,
    });

    // 加载当前回合（如果有）并连接 TurnDoc
    const configMap = mainDoc.getMap("config");
    const currentTurnNumber =
      (configMap.get("currentTurnNumber") as number) || 0;
    if (currentTurnNumber > 0) {
      // 设置 TurnDocProvider 配置
      const mpConfig = multiplayerProvider.getConfig();
      if (mpConfig) {
        turnDocProvider.setConfig({
          roomId: mpConfig.roomId,
          token: mpConfig.token,
          wsUrl: mpConfig.wsUrl,
        });
      }

      // ⚠️ 关键修改：区分 Host 和 Guest 的 TurnDoc 处理
      // - Host: 使用 createTurnDoc() 初始化完整结构
      // - Guest: 使用 joinTurnDoc() 创建空壳，等待服务器填充
      let turnDoc = subdocManager.getTurnDoc(roomId, currentTurnNumber);
      if (!turnDoc) {
        if (isHost) {
          // Host 重连时创建完整结构（理论上不应该走到这里，因为 Host 创建房间时已创建）
          turnDoc = subdocManager.createTurnDoc(roomId, currentTurnNumber);
        } else {
          // Guest 加入时使用 joinTurnDoc，不初始化结构
          turnDoc = subdocManager.joinTurnDoc(roomId, currentTurnNumber);
        }
      }
      await turnDocProvider.connect(roomId, currentTurnNumber, turnDoc);

      // 等待 TurnDoc 同步完成
      try {
        await turnDocProvider.waitForSync(roomId, currentTurnNumber, 10000);
      } catch (_syncError) {
        // TurnDoc 同步超时，继续执行
      }
    }

    // === Guest 存档处理：使用 saveId 匹配存档 ===
    // saveId 是核心匹配字段，所有玩家使用相同的 saveId
    const saves = yjsManager.listSaves();
    const currentSaveId = yjsManager.getCurrentSaveId();

    // 从 MainDoc 读取 saveId（核心匹配字段）
    // 复用上面已获取的 configMap
    const hostSaveId = configMap.get("saveId") as string | undefined;

    // 使用 saveId 匹配存档（100% 可靠）
    // saveId 就是存档的 id，所有玩家使用相同的 saveId
    const matchedSave = hostSaveId
      ? saves.find((s) => s.id === hostSaveId)
      : undefined;

    // 检查当前存档是否匹配
    const isCurrentMatching = currentSaveId === hostSaveId;

    let guestSaveId: string | null = currentSaveId ?? null;

    if (!isCurrentMatching) {
      if (matchedSave) {
        // 找到匹配的存档，加载它
        yjsManager.loadSave(matchedSave.id);
        guestSaveId = matchedSave.id;
      } else if (hostSaveId) {
        // 没有找到匹配的存档，使用 createSaveWithId 创建相同 saveId 的存档
        const guestMemberInfo: SaveMemberInfo = {
          displayName,
          role: isHost ? "host" : "guest",
        };

        // 使用 createSaveWithId 创建与 Host 相同 saveId 的存档
        guestSaveId = yjsManager.createSaveWithId(hostSaveId, {
          name: `联机存档 ${code}`,
          type: "multiplayer",
          roomId,
          roomCode: code,
          members: [guestMemberInfo],
        });

        yjsManager.loadSave(guestSaveId);
      } else {
        // 兼容旧逻辑：如果 MainDoc 没有 saveId，回退到创建新存档
        const guestMemberInfo: SaveMemberInfo = {
          displayName,
          role: isHost ? "host" : "guest",
        };

        guestSaveId = yjsManager.createSave({
          name: `联机存档 ${code}`,
          type: "multiplayer",
          roomId,
          roomCode: code,
          members: [guestMemberInfo],
        });

        yjsManager.loadSave(guestSaveId);
      }
    }

    // === Guest 消息迁移：使用 lastRoomId 判断是否需要迁移 ===
    if (guestSaveId) {
      const saveSlot = yjsManager.getSaveSlots().get(guestSaveId) as
        | Y.Map<unknown>
        | undefined;
      if (saveSlot) {
        // 使用 lastRoomId 判断是否需要迁移
        const lastRoomId = saveSlot.get("lastRoomId") as string | undefined;
        // 兼容旧存档：如果没有 lastRoomId，回退到 roomId
        const oldRoomId =
          lastRoomId || (saveSlot.get("roomId") as string | undefined);

        if (oldRoomId && oldRoomId !== roomId) {
          const oldConversationId = `room:${oldRoomId}:main`;
          const newConversationId = `room:${roomId}:main`;

          const messagesMap = saveSlot.get("messages") as
            | Y.Map<Y.Array<unknown>>
            | undefined;

          if (messagesMap) {
            const oldMessages = messagesMap.get(oldConversationId) as
              | Y.Array<unknown>
              | undefined;

            if (oldMessages && oldMessages.length > 0) {
              const messageCount = oldMessages.length;

              const rootDoc = yjsManager.getDoc();
              if (rootDoc) {
                rootDoc.transact(() => {
                  let newMessages = messagesMap.get(newConversationId) as
                    | Y.Array<unknown>
                    | undefined;
                  if (!newMessages) {
                    newMessages = new Y.Array<unknown>();
                    messagesMap.set(newConversationId, newMessages);
                  }

                  const migratedMessages: unknown[] = [];
                  for (let i = 0; i < messageCount; i++) {
                    const msg = oldMessages.get(i) as Record<string, unknown>;
                    migratedMessages.push({
                      ...msg,
                      conversationId: newConversationId,
                    });
                  }

                  newMessages.insert(newMessages.length, migratedMessages);
                  messagesMap.delete(oldConversationId);
                });
              }
            }
          }
        }
      }
    }

    // 更新存档的房间配置（包括 lastRoomId）
    if (guestSaveId) {
      yjsManager.updateSaveRoomConfig(guestSaveId, {
        roomId,
        lastRoomId: roomId, // 更新 lastRoomId 为当前 roomId
        roomCode: code,
        maxPlayers,
        turnDuration,
      });
    }

    // ⚠️ SyncBridge 改造：移除 MEMBER_JOINED 和 CONNECTED 事件的 emit
    // 这些事件将由 SyncBridge 通过 Yjs 状态变化自动派生
    // - MEMBER_JOINED: 由 members Map 变化触发（成员添加到 membersMap 时）
    // - CONNECTED: 由 MultiplayerProvider 状态回调触发（保留在 index.ts）

    // === 跨设备续玩优化：更新角色的 operatorUserId ===
    // 当用户通过 uniqueTag 匹配到角色时，更新 operatorUserId 为当前设备的 userId
    // 这样后续操作可以直接通过 userId 匹配，更高效
    const uniqueTag = getUniqueTag();
    if (uniqueTag) {
      const charactersMap = mainDoc.getMap("characters") as Y.Map<
        Y.Map<unknown>
      >;
      charactersMap.forEach((charMap, characterId) => {
        const operatorUniqueTag = charMap.get("operatorUniqueTag") as string;
        const operatorUserId = charMap.get("operatorUserId") as string;

        // 如果 uniqueTag 匹配但 userId 不匹配，说明是跨设备续玩
        if (operatorUniqueTag === uniqueTag && operatorUserId !== userId) {
          charMap.set("operatorUserId", userId);
          charMap.set("updatedAt", now);
        }
      });
    }

    return { success: true, data: { roomId, isHost } };
  } catch (error) {
    // 清理
    multiplayerProvider.disconnect();

    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 离开房间 =====

/**
 * 离开房间命令处理器
 *
 * 流程：
 * 1. 检查是否为房主
 * 2. 如果是房主，设置 disbanded 标记（通知其他成员）
 * 3. 写入 EventMeta（供 SyncBridge 派生正确事件类型）
 * 4. 从 Yjs 文档中删除成员（触发同步）
 * 5. 通知后端移除成员
 * 6. 断开 WebSocket 连接
 * 7. 卸载本地文档
 * 8. 如果是房主，通知服务器删除房间
 *
 * ⚠️ SyncBridge 改造：
 * - MEMBER_LEFT 事件由 SyncBridge 派生（基于 membersLeft 变化）
 * - 通过 EventMeta 传递 "leave" 意图，派生正确的事件类型
 * - DISCONNECTED 事件由 MultiplayerProvider 状态回调触发
 */
export async function leaveRoomHandler(
  payload: LeaveRoomPayload,
  _context: CommandContext
): Promise<CommandResult<void>> {
  try {
    const { roomId, userId } = payload;
    const now = Date.now();

    const mainDoc = subdocManager.getMainDoc(roomId);
    let isHost = false;

    if (!mainDoc) {
      // 如果没有本地文档，只需断开连接
      multiplayerProvider.disconnect();
      return { success: true };
    }

    // 检查是否为房主
    const metadataMap = mainDoc.getMap("metadata");
    const hostUserId = metadataMap.get("hostUserId") as string | undefined;
    isHost = hostUserId === userId;

    const membersMap = mainDoc.getMap("members") as Y.Map<Member>;
    const member = membersMap.get(userId);

    if (isHost) {
      // 房主解散房间：设置 disbanded 标记（这会通过 Yjs 同步到其他成员）
      metadataMap.set("disbanded", true);
      metadataMap.set("disbandedAt", now);

      // 等待一小段时间让 Yjs 同步 disbanded 标记
      await new Promise((resolve) => setTimeout(resolve, 300));
    } else if (member) {
      // ⚠️ SyncBridge 改造：先写入 EventMeta，再删除成员
      // 这样 SyncBridge 在检测到成员离开时可以读取元数据派生正确的事件类型
      writeMemberActionMeta(roomId, userId, {
        action: "leave",
        at: now,
      });

      // 非房主：从成员列表中删除（这会通过 Yjs 同步到其他客户端）
      membersMap.delete(userId);
    }

    // ⚠️ SyncBridge 改造：移除 MEMBER_LEFT 和 DISCONNECTED 事件的 emit
    // 这些事件将由 SyncBridge 和 MultiplayerProvider 自动派生
    // - MEMBER_LEFT: 由 SyncBridge 派生（基于 membersLeft + EventMeta）
    // - DISCONNECTED: 由 MultiplayerProvider 状态回调触发

    // 非房主：通知后端移除成员
    if (!isHost) {
      try {
        await apiClient.removeMember({ roomId, userId });
      } catch (_error) {
        // 移除失败不影响离开流程
      }
    }

    // 断开 HistoryDoc 连接
    historyDocProvider.disconnect(roomId);

    // 断开所有 TurnDoc 连接
    turnDocProvider.disconnectAll();

    // 断开 WebSocket 连接
    multiplayerProvider.disconnect();

    // 卸载本地文档缓存
    subdocManager.leaveRoom(roomId);

    // 如果是房主，通知服务器删除房间
    if (isHost) {
      try {
        await apiClient.deleteRoom(roomId, userId);
      } catch (_error) {
        // 删除失败不影响离开流程
      }
    }

    return { success: true };
  } catch (error) {
    // 确保断开连接
    multiplayerProvider.disconnect();

    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 更新成员状态 =====

interface UpdateMemberStatusPayload {
  roomId: string;
  userId: string;
  status: "online" | "away" | "offline";
}

/**
 * 更新成员状态命令处理器
 */
export async function updateMemberStatusHandler(
  payload: UpdateMemberStatusPayload,
  _context: CommandContext
): Promise<CommandResult<void>> {
  try {
    const { roomId, userId, status } = payload;

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    const membersMap = mainDoc.getMap("members") as Y.Map<Member>;
    const member = membersMap.get(userId);

    if (member) {
      const updatedMember: Member = {
        ...member,
        status,
        lastActiveAt: Date.now(),
      };
      membersMap.set(userId, updatedMember);

      // 发布事件
      eventBus.emit(
        eventBus.createEvent(RoomEvents.MEMBER_STATUS_UPDATED, {
          roomId,
          userId,
          status,
        })
      );
    }

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 开始新回合 =====

/**
 * 开始新回合命令处理器
 */
export async function startTurnHandler(
  payload: StartTurnPayload,
  _context: CommandContext
): Promise<CommandResult<{ turnNumber: number }>> {
  try {
    const { roomId, duration } = payload;
    const now = Date.now();

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    // 获取当前回合号并递增
    const configMap = mainDoc.getMap("config");
    const currentTurnNumber =
      (configMap.get("currentTurnNumber") as number) || 0;
    const newTurnNumber = currentTurnNumber + 1;

    // 获取回合时长
    const metadataMap = mainDoc.getMap("metadata");
    const turnDuration =
      duration || (metadataMap.get("turnDuration") as number) || 5 * 60 * 1000;
    const deadline = now + turnDuration;

    // 断开旧回合的 TurnDoc
    if (currentTurnNumber > 0) {
      turnDocProvider.disconnect(roomId, currentTurnNumber);
    }

    // 创建新回合文档
    const turnDoc = subdocManager.createTurnDoc(
      roomId,
      newTurnNumber,
      deadline
    );

    // 更新 MainDoc 的当前回合号
    configMap.set("currentTurnNumber", newTurnNumber);

    // 在 MainDoc 中注册引用
    const turnDocRefs = mainDoc.getMap("turnDocRefs");
    turnDocRefs.set(String(newTurnNumber), turnDoc.guid);

    // 连接新回合的 TurnDoc
    const mpConfig = multiplayerProvider.getConfig();
    if (mpConfig) {
      turnDocProvider.setConfig({
        roomId: mpConfig.roomId,
        token: mpConfig.token,
        wsUrl: mpConfig.wsUrl,
      });
      await turnDocProvider.connect(roomId, newTurnNumber, turnDoc);
    }

    // ⚠️ SyncBridge 改造：移除 TURN_STARTED 事件的 emit
    // 这个事件将由 SyncBridge 通过检测 currentTurnNumber 变化自动派生

    return { success: true, data: { turnNumber: newTurnNumber } };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 提交行动 =====

/**
 * 提交行动命令处理器
 */
export async function submitActionHandler(
  payload: SubmitActionPayload,
  _context: CommandContext
): Promise<CommandResult<void>> {
  try {
    const { roomId, turnNumber, userId, content, metadata } = payload;
    const now = Date.now();

    const turnDoc = subdocManager.getTurnDoc(roomId, turnNumber);
    if (!turnDoc) {
      return {
        success: false,
        error: `TurnDoc not found: ${roomId}:${turnNumber}`,
      };
    }

    // 添加行动
    const actionsMap = turnDoc.getMap("actions");
    actionsMap.set(userId, {
      userId,
      content,
      submittedAt: now,
      metadata,
    });

    // 获取已提交数量
    const submittedCount = actionsMap.size;
    const totalPlayers = subdocManager.getMemberCount(roomId);

    // 发布事件
    const event: ActionSubmittedEvent = {
      roomId,
      turnNumber,
      userId,
      submittedAt: now,
      submittedCount,
      totalPlayers,
    };
    eventBus.emit(eventBus.createEvent(RoomEvents.ACTION_SUBMITTED, event));

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 转让房主 =====

/**
 * 转让房主命令处理器
 */
export async function transferHostHandler(
  payload: TransferHostPayload,
  _context: CommandContext
): Promise<CommandResult<void>> {
  try {
    const { roomId, currentHostId, newHostId } = payload;
    const now = Date.now();

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    const membersMap = mainDoc.getMap("members") as Y.Map<Member>;
    const currentHost = membersMap.get(currentHostId);
    const newHost = membersMap.get(newHostId);

    if (!currentHost || currentHost.role !== "host") {
      return {
        success: false,
        error: `Current host not found or not a host: ${currentHostId}`,
      };
    }

    if (!newHost) {
      return { success: false, error: `New host not found: ${newHostId}` };
    }

    // ⚠️ SyncBridge 改造：先写入 EventMeta，再更新状态
    // 这样 SyncBridge 在检测到 hostUserId 变化时可以读取元数据派生正确的事件类型
    writeHostTransferMeta(roomId, {
      from: currentHostId,
      to: newHostId,
      type: "manual",
      at: now,
    });

    // 更新角色
    membersMap.set(currentHostId, { ...currentHost, role: "guest" });
    membersMap.set(newHostId, { ...newHost, role: "host" });

    // 更新 metadata
    const metadataMap = mainDoc.getMap("metadata");
    metadataMap.set("hostUserId", newHostId);
    metadataMap.set("updatedAt", now);

    // ⚠️ SyncBridge 改造：移除 HOST_TRANSFERRED 事件的 emit
    // 这个事件将由 SyncBridge 通过检测 hostUserId 变化 + EventMeta 自动派生

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 查询房间 =====

/**
 * 查询房间命令处理器
 *
 * 用于加入房间前预览房间信息
 *
 * 流程：
 * 1. 调用 API 查询房间
 * 2. 返回房间预览信息
 */
export async function queryRoomHandler(
  payload: QueryRoomPayload,
  _context: CommandContext
): Promise<CommandResult<QueryRoomResult>> {
  const { code } = payload;

  // 确保 API 客户端已配置
  const config = getMultiplayerConfig();
  if (!apiClient.getBaseUrl()) {
    apiClient.setBaseUrl(config.apiUrl);
  }

  try {
    // 调用 API 查询房间详情
    const queryResponse = await apiClient.queryRoomDetails(code);

    return {
      success: true,
      data: {
        roomId: queryResponse.roomId,
        name: queryResponse.name || `房间 ${code}`,
        hostName: queryResponse.hostDisplayName || "未知",
        memberCount: queryResponse.memberCount || 1,
        maxPlayers: queryResponse.maxPlayers || 8,
      },
    };
  } catch (error) {
    if (error instanceof ApiError) {
      if (error.status === 404) {
        return { success: false, error: "房间不存在或已过期" };
      }
    }

    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== Phase 管理 =====

import type {
  AdvancePhasePayload,
  CompletePhasePayload,
  EndGamePayload,
  EnterPhasePayload,
  StartGamePayload,
} from "@/domain/commands/room";
import {
  createPhaseInstance,
  DEFAULT_FLOW_TEMPLATE,
  getNextPhaseInfo,
  PhaseTypes,
  type PhaseInstance,
  type PhaseType,
} from "@/domain/entities/phase";
import type {
  PhaseAdvancedEvent,
  PhaseCompletedEvent,
} from "@/domain/events/room";

/**
 * 进入阶段命令处理器
 *
 * 创建一个新的阶段实例并将其设置为当前阶段
 */
export async function enterPhaseHandler(
  payload: EnterPhasePayload,
  _context: CommandContext
): Promise<CommandResult<{ phaseId: string }>> {
  try {
    const { roomId, phaseType, configOverride, turnNumber } = payload;

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    // 创建阶段实例
    const phaseInstance = createPhaseInstance(
      phaseType as PhaseType,
      configOverride
    );

    // 根据 turnNumber 决定存储位置
    if (turnNumber === 0) {
      // 预游戏阶段，存储在 MainDoc.preGamePhases
      const preGamePhases = mainDoc.getArray("preGamePhases");
      preGamePhases.push([phaseInstance]);
    } else {
      // 回合内阶段，存储在 TurnDoc.phases
      const turnDoc = subdocManager.getTurnDoc(roomId, turnNumber);
      if (!turnDoc) {
        return {
          success: false,
          error: `TurnDoc not found: ${roomId}:${turnNumber}`,
        };
      }
      const phases = turnDoc.getArray("phases");
      phases.push([phaseInstance]);

      // 更新 TurnDoc 的当前阶段索引
      turnDoc.getMap("config").set("currentPhaseIndex", phases.length - 1);
    }

    // 更新 MainDoc 的当前阶段 ID
    const configMap = mainDoc.getMap("config");
    configMap.set("currentPhaseId", phaseInstance.id);

    // ⚠️ SyncBridge 改造：移除 PHASE_ENTERED 事件的 emit
    // 这个事件将由 SyncBridge 通过检测 currentPhaseId 变化自动派生

    return { success: true, data: { phaseId: phaseInstance.id } };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * 完成当前阶段命令处理器
 */
export async function completePhaseHandler(
  payload: CompletePhasePayload,
  _context: CommandContext
): Promise<CommandResult<void>> {
  try {
    const { roomId, phaseId, data } = payload;
    const now = Date.now();

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    const configMap = mainDoc.getMap("config");
    const currentPhaseId = configMap.get("currentPhaseId") as string | null;

    if (currentPhaseId !== phaseId) {
      return {
        success: false,
        error: `Phase ID mismatch: expected ${currentPhaseId}, got ${phaseId}`,
      };
    }

    const currentTurnNumber =
      (configMap.get("currentTurnNumber") as number) || 0;

    // 查找并更新阶段实例
    let phaseInstance: PhaseInstance | null = null;
    let phaseType: string = "";

    if (currentTurnNumber === 0) {
      // 预游戏阶段
      const preGamePhases = mainDoc.getArray("preGamePhases");
      for (let i = 0; i < preGamePhases.length; i++) {
        const phase = preGamePhases.get(i) as PhaseInstance;
        if (phase.id === phaseId) {
          phaseInstance = {
            ...phase,
            completedAt: now,
            data: { ...phase.data, ...data },
            updatedAt: now,
          };
          phaseType = phase.type;
          preGamePhases.delete(i);
          preGamePhases.insert(i, [phaseInstance]);
          break;
        }
      }
    } else {
      // 回合内阶段
      const turnDoc = subdocManager.getTurnDoc(roomId, currentTurnNumber);
      if (turnDoc) {
        const phases = turnDoc.getArray("phases");
        for (let i = 0; i < phases.length; i++) {
          const phase = phases.get(i) as PhaseInstance;
          if (phase.id === phaseId) {
            phaseInstance = {
              ...phase,
              completedAt: now,
              data: { ...phase.data, ...data },
              updatedAt: now,
            };
            phaseType = phase.type;
            phases.delete(i);
            phases.insert(i, [phaseInstance]);
            break;
          }
        }
      }
    }

    if (!phaseInstance) {
      return { success: false, error: `Phase not found: ${phaseId}` };
    }

    // 发布事件
    const event: PhaseCompletedEvent = {
      roomId,
      phaseId,
      phaseType,
      turnNumber: currentTurnNumber,
      data: phaseInstance.data,
      completedAt: now,
    };
    eventBus.emit(eventBus.createEvent(RoomEvents.PHASE_COMPLETED, event));

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * 推进到下一阶段命令处理器
 *
 * 自动根据流程模板决定下一阶段
 */
export async function advancePhaseHandler(
  payload: AdvancePhasePayload,
  _context: CommandContext
): Promise<CommandResult<{ nextPhaseId: string; isNewTurn: boolean }>> {
  try {
    const { roomId } = payload;
    const now = Date.now();

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    const configMap = mainDoc.getMap("config");
    const currentPhaseId = configMap.get("currentPhaseId") as string | null;
    const currentTurnNumber =
      (configMap.get("currentTurnNumber") as number) || 0;
    const currentPhaseIndex =
      (configMap.get("currentPhaseIndex") as number) || 0;

    // 获取当前阶段类型
    let currentPhaseType: PhaseType | null = null;

    if (currentTurnNumber === 0) {
      const preGamePhases = mainDoc.getArray("preGamePhases");
      if (preGamePhases.length > 0) {
        const lastPhase = preGamePhases.get(
          preGamePhases.length - 1
        ) as PhaseInstance;
        currentPhaseType = lastPhase.type as PhaseType;
      }
    } else {
      const turnDoc = subdocManager.getTurnDoc(roomId, currentTurnNumber);
      if (turnDoc) {
        const phases = turnDoc.getArray("phases");
        if (phases.length > 0) {
          const lastPhase = phases.get(phases.length - 1) as PhaseInstance;
          currentPhaseType = lastPhase.type as PhaseType;
        }
      }
    }

    if (!currentPhaseType) {
      return { success: false, error: "No current phase to advance from" };
    }

    // 使用默认流程模板计算下一阶段
    const nextInfo = getNextPhaseInfo(
      DEFAULT_FLOW_TEMPLATE,
      currentPhaseType,
      currentTurnNumber,
      currentPhaseIndex
    );

    if (!nextInfo) {
      // 流程结束
      return { success: false, error: "Flow has ended, no next phase" };
    }

    const { nextPhase, nextTurnNumber, nextPhaseIndex, isNewTurn } = nextInfo;

    // 如果是新回合，需要先创建 TurnDoc
    // ⚠️ 关键修改：只有 Host 才能创建新回合的 TurnDoc
    // Guest 的回合切换由 RoomSyncBridge 监听 currentTurnNumber 变化自动处理
    if (isNewTurn && nextTurnNumber > 0) {
      // 获取当前用户是否为 Host
      const store = useRoomStore.getState();
      const isHost = store.currentRoom?.isHost ?? false;

      // 断开旧回合的 TurnDoc
      if (currentTurnNumber > 0) {
        turnDocProvider.disconnect(roomId, currentTurnNumber);
      }

      if (isHost) {
        // Host: 创建新回合的 TurnDoc 并初始化完整结构
        const metadataMap = mainDoc.getMap("metadata");
        const turnDuration =
          (metadataMap.get("turnDuration") as number) || 5 * 60 * 1000;
        const deadline = now + turnDuration;

        const newTurnDoc = subdocManager.createTurnDoc(
          roomId,
          nextTurnNumber,
          deadline
        );

        // 更新 MainDoc 的当前回合号（这会触发 Guest 的 RoomSyncBridge 自动切换）
        configMap.set("currentTurnNumber", nextTurnNumber);

        // 在 MainDoc 中注册引用
        const turnDocRefs = mainDoc.getMap("turnDocRefs");
        turnDocRefs.set(String(nextTurnNumber), newTurnDoc.guid);

        // 连接新回合的 TurnDoc
        const mpConfig = multiplayerProvider.getConfig();
        if (mpConfig) {
          turnDocProvider.setConfig({
            roomId: mpConfig.roomId,
            token: mpConfig.token,
            wsUrl: mpConfig.wsUrl,
          });
          await turnDocProvider.connect(roomId, nextTurnNumber, newTurnDoc);
        }
      } else {
        // Guest: 不创建 TurnDoc，只更新本地状态
        // TurnDoc 的创建和连接由 RoomSyncBridge 监听 currentTurnNumber 变化自动处理
        // 这里只需要等待 MainDoc 同步后，RoomSyncBridge 会自动调用 joinTurnDoc
      }
    }

    // 创建下一阶段实例
    const nextPhaseInstance = createPhaseInstance(
      nextPhase.type,
      nextPhase.config
    );

    // 存储新阶段
    if (nextTurnNumber === 0) {
      const preGamePhases = mainDoc.getArray("preGamePhases");
      preGamePhases.push([nextPhaseInstance]);
    } else if (nextTurnNumber > 0) {
      const turnDoc = subdocManager.getTurnDoc(roomId, nextTurnNumber);
      if (turnDoc) {
        const phases = turnDoc.getArray("phases");
        phases.push([nextPhaseInstance]);
        turnDoc.getMap("config").set("currentPhaseIndex", phases.length - 1);
      }
    } else {
      // nextTurnNumber < 0 表示结束阶段，存储在 preGamePhases（或可单独存储）
      const preGamePhases = mainDoc.getArray("preGamePhases");
      preGamePhases.push([nextPhaseInstance]);
    }

    // 更新配置
    configMap.set("currentPhaseId", nextPhaseInstance.id);
    configMap.set("currentPhaseIndex", nextPhaseIndex);

    // 发布推进事件（本地业务事件，保留 - SyncBridge 不派生 PHASE_ADVANCED）
    const advanceEvent: PhaseAdvancedEvent = {
      roomId,
      previousPhaseId: currentPhaseId || "",
      previousPhaseType: currentPhaseType,
      nextPhaseId: nextPhaseInstance.id,
      nextPhaseType: nextPhase.type,
      turnNumber: nextTurnNumber,
      isNewTurn,
      advancedAt: now,
    };
    eventBus.emit(
      eventBus.createEvent(RoomEvents.PHASE_ADVANCED, advanceEvent)
    );

    // ⚠️ SyncBridge 改造：移除 PHASE_ENTERED 事件的 emit
    // 这个事件将由 SyncBridge 通过检测 currentPhaseId 变化自动派生
    // TURN_STARTED 也由 SyncBridge 派生（当 isNewTurn && currentTurnNumber 增加时）

    return {
      success: true,
      data: { nextPhaseId: nextPhaseInstance.id, isNewTurn },
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * 开始游戏命令处理器
 *
 * 从 lobby 阶段进入第一回合
 *
 * ⚠️ 角色检查：开始游戏前会检查所有成员是否都有角色
 */
export async function startGameHandler(
  payload: StartGamePayload,
  _context: CommandContext
): Promise<CommandResult<{ turnNumber: number }>> {
  try {
    const { roomId, userId } = payload;
    const now = Date.now();

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    // 验证是否为 Host
    if (!subdocManager.isHost(roomId, userId)) {
      return { success: false, error: "Only host can start the game" };
    }

    // === 角色检查：确保所有成员都有角色 ===
    const membersMap = mainDoc.getMap("members") as Y.Map<Member>;
    const charactersMap = mainDoc.getMap("characters") as Y.Map<Y.Map<unknown>>;

    // 收集所有成员的 userId
    const memberUserIds: string[] = [];
    membersMap.forEach((_member, odUserId) => {
      memberUserIds.push(odUserId);
    });

    // 收集所有角色的 operatorUserId
    const characterOperatorIds = new Set<string>();
    charactersMap.forEach((charMap) => {
      const operatorUserId = charMap.get("operatorUserId") as string;
      if (operatorUserId) {
        characterOperatorIds.add(operatorUserId);
      }
    });

    // 检查是否有成员没有角色
    const membersWithoutCharacter = memberUserIds.filter(
      (odUserId) => !characterOperatorIds.has(odUserId)
    );

    if (membersWithoutCharacter.length > 0) {
      // 获取没有角色的成员名称
      const missingNames: string[] = [];
      membersWithoutCharacter.forEach((odUserId) => {
        const member = membersMap.get(odUserId);
        if (member) {
          missingNames.push(member.displayName);
        }
      });

      return {
        success: false,
        error: `以下玩家尚未创建角色：${missingNames.join("、")}`,
      };
    }

    const configMap = mainDoc.getMap("config");
    const currentTurnNumber =
      (configMap.get("currentTurnNumber") as number) || 0;

    if (currentTurnNumber > 0) {
      // 续玩场景：从 currentTurnNumber + 1 开始新回合
      const metadataMap = mainDoc.getMap("metadata");
      if (metadataMap.get("status") !== "playing") {
        metadataMap.set("status", "playing");
        metadataMap.set("updatedAt", now);
      }

      const turnDuration =
        (metadataMap.get("turnDuration") as number) || 5 * 60 * 1000;
      const deadline = now + turnDuration;
      const nextTurnNumber = currentTurnNumber + 1;

      const turnDoc = subdocManager.createTurnDoc(
        roomId,
        nextTurnNumber,
        deadline
      );

      // 更新 MainDoc 配置为新回合
      configMap.set("currentTurnNumber", nextTurnNumber);

      // 注册 TurnDoc 引用
      const turnDocRefs = mainDoc.getMap("turnDocRefs");
      turnDocRefs.set(String(nextTurnNumber), turnDoc.guid);

      // 连接 TurnDoc
      const mpConfig = multiplayerProvider.getConfig();
      if (mpConfig) {
        turnDocProvider.setConfig({
          roomId: mpConfig.roomId,
          token: mpConfig.token,
          wsUrl: mpConfig.wsUrl,
        });
        await turnDocProvider.connect(roomId, nextTurnNumber, turnDoc);
      }

      // 创建首个阶段（action_input）
      const firstPhase = createPhaseInstance(PhaseTypes.ACTION_INPUT, {
        deadline,
      });
      const phases = turnDoc.getArray("phases");
      phases.push([firstPhase]);
      turnDoc.getMap("config").set("currentPhaseIndex", 0);

      // 更新当前阶段 ID
      configMap.set("currentPhaseId", firstPhase.id);
      configMap.set("currentPhaseIndex", 0);

      return { success: true, data: { turnNumber: nextTurnNumber } };
    }

    // 完成当前 lobby 阶段
    const currentPhaseId = configMap.get("currentPhaseId") as string | null;
    if (currentPhaseId) {
      const preGamePhases = mainDoc.getArray("preGamePhases");
      for (let i = 0; i < preGamePhases.length; i++) {
        const phase = preGamePhases.get(i) as PhaseInstance;
        if (phase.id === currentPhaseId && phase.type === PhaseTypes.LOBBY) {
          const completedPhase: PhaseInstance = {
            ...phase,
            completedAt: now,
            updatedAt: now,
          };
          preGamePhases.delete(i);
          preGamePhases.insert(i, [completedPhase]);
          break;
        }
      }
    }

    // 更新房间状态为 playing
    const metadataMap = mainDoc.getMap("metadata");
    metadataMap.set("status", "playing");
    metadataMap.set("updatedAt", now);

    // 创建第一回合
    const turnDuration =
      (metadataMap.get("turnDuration") as number) || 5 * 60 * 1000;
    const deadline = now + turnDuration;
    const firstTurnNumber = 1;

    const turnDoc = subdocManager.createTurnDoc(
      roomId,
      firstTurnNumber,
      deadline
    );

    // 更新 MainDoc 配置
    configMap.set("currentTurnNumber", firstTurnNumber);

    // 注册 TurnDoc 引用
    const turnDocRefs = mainDoc.getMap("turnDocRefs");
    turnDocRefs.set(String(firstTurnNumber), turnDoc.guid);

    // 设置 TurnDocProvider 配置并连接 TurnDoc
    const mpConfig = multiplayerProvider.getConfig();
    if (mpConfig) {
      turnDocProvider.setConfig({
        roomId: mpConfig.roomId,
        token: mpConfig.token,
        wsUrl: mpConfig.wsUrl,
      });
      await turnDocProvider.connect(roomId, firstTurnNumber, turnDoc);
    }

    // 创建第一个回合阶段（action_input）
    const firstPhase = createPhaseInstance(PhaseTypes.ACTION_INPUT, {
      deadline,
    });
    const phases = turnDoc.getArray("phases");
    phases.push([firstPhase]);
    turnDoc.getMap("config").set("currentPhaseIndex", 0);

    // 更新当前阶段 ID
    configMap.set("currentPhaseId", firstPhase.id);
    configMap.set("currentPhaseIndex", 0);

    // ⚠️ SyncBridge 改造：移除所有由 SyncBridge 派生的事件 emit
    // - GAME_STARTED: 由 SyncBridge 检测 status: waiting → playing 派生
    // - TURN_STARTED: 由 SyncBridge 检测 currentTurnNumber 增加派生
    // - PHASE_ENTERED: 由 SyncBridge 检测 currentPhaseId 变化派生

    return { success: true, data: { turnNumber: firstTurnNumber } };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * 结束游戏命令处理器
 */
export async function endGameHandler(
  payload: EndGamePayload,
  _context: CommandContext
): Promise<CommandResult<void>> {
  try {
    const { roomId, userId } = payload;
    const now = Date.now();

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    // 验证是否为 Host
    if (!subdocManager.isHost(roomId, userId)) {
      return { success: false, error: "Only host can end the game" };
    }

    const configMap = mainDoc.getMap("config");
    const currentTurnNumber =
      (configMap.get("currentTurnNumber") as number) || 0;

    // 更新房间状态
    const metadataMap = mainDoc.getMap("metadata");
    metadataMap.set("status", "ended");
    metadataMap.set("updatedAt", now);

    // 创建结束阶段
    const endedPhase = createPhaseInstance(PhaseTypes.ENDED);
    const preGamePhases = mainDoc.getArray("preGamePhases");
    preGamePhases.push([endedPhase]);

    // 更新当前阶段
    configMap.set("currentPhaseId", endedPhase.id);
    configMap.set("currentTurnNumber", -1); // -1 表示游戏结束

    // ⚠️ SyncBridge 改造：移除 GAME_ENDED 事件的 emit
    // 这个事件将由 SyncBridge 通过检测 status: playing → ended 派生

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 延长回合时间 =====

/**
 * 延长回合截止时间 Payload
 */
export interface ExtendTurnDeadlinePayload {
  /** 房间 ID */
  roomId: string;
  /** 回合号 */
  turnNumber: number;
  /** 额外时间（毫秒） */
  additionalTime: number;
}

/**
 * 延长回合截止时间命令处理器
 *
 * 仅 Host 可调用，将当前回合的截止时间延长
 */
export async function extendTurnDeadlineHandler(
  payload: ExtendTurnDeadlinePayload,
  _context: CommandContext
): Promise<CommandResult<{ newDeadline: number }>> {
  try {
    const { roomId, turnNumber, additionalTime } = payload;
    const now = Date.now();

    // 获取 TurnDoc
    const turnDoc = subdocManager.getTurnDoc(roomId, turnNumber);
    if (!turnDoc) {
      return {
        success: false,
        error: `TurnDoc not found: ${roomId}:${turnNumber}`,
      };
    }

    // 获取当前截止时间
    const configMap = turnDoc.getMap("config");
    const currentDeadline = (configMap.get("deadline") as number) || now;

    // 计算新截止时间（从当前时间或原截止时间取较大值开始计算）
    const baseTime = Math.max(now, currentDeadline);
    const newDeadline = baseTime + additionalTime;

    // 更新截止时间
    configMap.set("deadline", newDeadline);
    configMap.set("updatedAt", now);

    // 发布事件
    eventBus.emit(
      eventBus.createEvent(RoomEvents.TURN_DEADLINE_EXTENDED, {
        roomId,
        turnNumber,
        previousDeadline: currentDeadline,
        newDeadline,
        additionalTime,
        extendedAt: now,
      })
    );

    return { success: true, data: { newDeadline } };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 强制开始回合 =====

/**
 * 强制开始回合 Payload
 */
export interface ForceStartTurnPayload {
  /** 房间 ID */
  roomId: string;
  /** 回合号 */
  turnNumber: number;
  /** 是否跳过未提交玩家（不使用默认行动） */
  skipUnsubmitted?: boolean;
}

/**
 * 强制开始回合命令处理器
 *
 * 仅 Host 可调用，立即锁定所有行动并进入下一阶段
 */
export async function forceStartTurnHandler(
  payload: ForceStartTurnPayload,
  _context: CommandContext
): Promise<CommandResult<void>> {
  try {
    const { roomId, turnNumber, skipUnsubmitted = false } = payload;
    const now = Date.now();

    // 获取 TurnDoc
    const turnDoc = subdocManager.getTurnDoc(roomId, turnNumber);
    if (!turnDoc) {
      return {
        success: false,
        error: `TurnDoc not found: ${roomId}:${turnNumber}`,
      };
    }

    // 锁定所有行动
    const actionsMap = turnDoc.getMap("actions");
    const configMap = turnDoc.getMap("config");

    // 更新锁定状态
    configMap.set("isLocked", true);
    configMap.set("lockedAt", now);
    configMap.set("lockReason", "force_start");

    // 标记跳过的玩家
    if (skipUnsubmitted) {
      const mainDoc = subdocManager.getMainDoc(roomId);
      if (mainDoc) {
        const membersMap = mainDoc.getMap("members");
        const skippedPlayers: string[] = [];

        membersMap.forEach((_member, oderId) => {
          if (!actionsMap.has(oderId)) {
            skippedPlayers.push(oderId);
          }
        });

        configMap.set("skippedPlayers", skippedPlayers);
      }
    }

    // 发布锁定事件
    eventBus.emit(
      eventBus.createEvent(RoomEvents.ACTION_LOCKED, {
        roomId,
        turnNumber,
        lockedAt: now,
        reason: "force_start",
        skippedPlayers: skipUnsubmitted
          ? (configMap.get("skippedPlayers") as string[]) || []
          : [],
      })
    );

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 锁定行动 =====

/**
 * 锁定行动 Payload
 */
export interface LockActionPayload {
  /** 房间 ID */
  roomId: string;
  /** 回合号 */
  turnNumber: number;
  /** 锁定原因 */
  reason: "timeout" | "all_submitted" | "force_start" | "host_decision";
}

/**
 * 锁定行动命令处理器
 *
 * 锁定当前回合的所有行动，阻止进一步修改
 */
export async function lockActionHandler(
  payload: LockActionPayload,
  _context: CommandContext
): Promise<CommandResult<void>> {
  try {
    const { roomId, turnNumber, reason } = payload;
    const now = Date.now();

    // 获取 MainDoc（用于检查 Host 身份）
    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    // 获取 TurnDoc
    const turnDoc = subdocManager.getTurnDoc(roomId, turnNumber);
    if (!turnDoc) {
      return {
        success: false,
        error: `TurnDoc not found: ${roomId}:${turnNumber}`,
      };
    }

    const configMap = turnDoc.getMap("config");

    // 检查是否已锁定
    if (configMap.get("isLocked")) {
      return { success: true }; // 已锁定，无需重复操作
    }

    // 更新锁定状态
    configMap.set("isLocked", true);
    configMap.set("lockedAt", now);
    configMap.set("lockReason", reason);

    // 发布事件
    eventBus.emit(
      eventBus.createEvent(RoomEvents.ACTION_LOCKED, {
        roomId,
        turnNumber,
        lockedAt: now,
        reason,
      })
    );

    // AI 处理由 AI 模块通过事件订阅自行触发（解耦设计）
    // 参见 src/modules/room/index.ts 中的 setupAiEventSubscriptions()

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 完成回合 =====

import type { PlayerAction, StateChange } from "@/core/yjs/room/types";
import {
  convertTurnToMessages,
  toMessageEntities,
} from "../services/turn-converter";

/**
 * 完成回合命令处理器
 *
 * 流程：
 * 1. 获取 TurnDoc 数据
 * 2. 转换为消息格式
 * 3. 双写：TurnDoc 归档 + HistoryDoc 消息存储
 * 4. 发布 TURN_COMPLETED 事件
 */
export async function completeTurnHandler(
  payload: CompleteTurnPayload,
  _context: CommandContext
): Promise<CommandResult<void>> {
  try {
    const { roomId, turnNumber, aiResponse, stateChanges } = payload;
    const now = Date.now();

    // 获取 MainDoc
    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    // 获取 TurnDoc
    const turnDoc = subdocManager.getTurnDoc(roomId, turnNumber);
    if (!turnDoc) {
      return {
        success: false,
        error: `TurnDoc not found: ${roomId}:${turnNumber}`,
      };
    }

    // 获取成员信息
    const membersMap = mainDoc.getMap("members") as Y.Map<Member>;
    const members = new Map<string, Member>();
    membersMap.forEach((member, id) => {
      members.set(id, member);
    });

    // 获取角色信息（用于显示角色名称而非玩家名称）
    const charactersMap = mainDoc.getMap("characters") as Y.Map<Y.Map<unknown>>;
    const characters: Character[] = [];
    charactersMap.forEach((charMap) => {
      try {
        const character: Character = {
          id: charMap.get("id") as string,
          name: charMap.get("name") as string,
          creatorUniqueTag: charMap.get("creatorUniqueTag") as string,
          operatorUserId: charMap.get("operatorUserId") as string,
          operatorUniqueTag: charMap.get("operatorUniqueTag") as string,
          status: charMap.get("status") as Character["status"],
          createdAt: charMap.get("createdAt") as number,
          updatedAt: charMap.get("updatedAt") as number,
          attributes: charMap.get("attributes") as
            | Record<string, unknown>
            | undefined,
        };
        characters.push(character);
      } catch (err) {
        console.warn("[completeTurnHandler] Failed to extract character:", err);
      }
    });

    // 获取玩家行动
    const actionsMap = turnDoc.getMap("actions") as Y.Map<PlayerAction>;
    const actions = new Map<string, PlayerAction>();
    actionsMap.forEach((action, userId) => {
      actions.set(userId, action);
    });

    // 读取 TurnDoc 的 AI 响应（作为默认值）
    const aiResponseText = turnDoc.getText("aiResponse");
    const resolvedAiResponse =
      aiResponse !== undefined ? aiResponse : aiResponseText.toString();

    // 更新 TurnDoc 的 AI 响应（仅在传入时才覆盖）
    if (aiResponse !== undefined) {
      aiResponseText.delete(0, aiResponseText.length);
      aiResponseText.insert(0, aiResponse);
    }

    // 检查是否已完成（防止重复调用）
    const turnConfig = turnDoc.getMap("config");
    const existingStatus = turnConfig.get("status") as string | undefined;
    if (existingStatus === "completed") {
      return { success: true };
    }

    // 更新 TurnDoc 状态
    turnConfig.set("status", "completed");
    turnConfig.set("completedAt", now);

    // 存储状态变更（仅当传入时才写入 TurnDoc）
    const stateChangesArray = turnDoc.getArray("stateChanges");
    if (stateChanges && stateChanges.length > 0) {
      for (const change of stateChanges) {
        stateChangesArray.push([
          {
            type: change.type,
            targetId: change.targetId,
            before: change.before,
            after: change.after,
            timestamp: now,
          } as StateChange,
        ]);
      }
    }

    // 归档使用的状态变更（未传入则从 TurnDoc 读取）
    const resolvedStateChanges: StateChange[] =
      stateChanges && stateChanges.length > 0
        ? stateChanges.map((sc) => ({
            ...sc,
            timestamp: now,
          }))
        : (stateChangesArray.toArray() as StateChange[]);

    // 获取会话 ID（使用默认的房间主会话）
    const conversationId = `room:${roomId}:main`;

    // 转换回合数据为消息格式（传入角色信息以显示角色名称）
    const conversionResult = convertTurnToMessages({
      turnNumber,
      actions,
      members,
      characters,
      aiResponse: resolvedAiResponse,
      completedAt: now,
      conversationId,
    });

    // 加载 HistoryDoc 并写入消息
    const historyDoc = await subdocManager.loadHistoryDoc(roomId);
    const messagesMap = historyDoc.getMap("messages") as Y.Map<
      Y.Array<unknown>
    >;

    // 确保会话消息数组存在
    let messagesArray = messagesMap.get(conversationId) as
      | Y.Array<unknown>
      | undefined;
    if (!messagesArray) {
      messagesArray = new Y.Array<unknown>();
      messagesMap.set(conversationId, messagesArray);
    }

    // 转换为 Message 实体并写入
    const messageEntities = toMessageEntities(
      conversionResult.messages,
      conversationId
    );
    for (const msg of messageEntities) {
      messagesArray.push([msg]);
    }

    // 归档回合数据到 HistoryDoc
    const archivedTurns = historyDoc.getArray("archivedTurns");
    const archiveData = {
      turnNumber,
      completedAt: now,
      actions: Object.fromEntries(actions),
      stateChanges: resolvedStateChanges,
      aiResponseLength: resolvedAiResponse.length,
    };

    // 压缩并存储（简化版：直接存储 JSON）
    archivedTurns.push([
      {
        turnNumber,
        completedAt: now,
        compressedData: JSON.stringify(archiveData),
      },
    ]);

    // === 新增：写入 SaveSlot（持久化） ===
    const currentSaveId = yjsManager.getCurrentSaveId();

    if (currentSaveId) {
      const saveSlot = yjsManager.getSaveSlots().get(currentSaveId) as
        | Y.Map<unknown>
        | undefined;
      if (saveSlot) {
        // 1. 写入消息到 SaveSlot
        const saveMessagesMap = saveSlot.get("messages") as
          | Y.Map<Y.Array<unknown>>
          | undefined;
        if (saveMessagesMap) {
          let saveMsgArray = saveMessagesMap.get(conversationId) as
            | Y.Array<unknown>
            | undefined;
          if (!saveMsgArray) {
            saveMsgArray = new Y.Array<unknown>();
            saveMessagesMap.set(conversationId, saveMsgArray);
          }

          for (const msg of messageEntities) {
            saveMsgArray.push([msg]);
          }
        }

        // 2. 更新回合号
        saveSlot.set("currentTurnNumber", turnNumber);

        // 3. 归档回合数据到 SaveSlot（可选，用于回放）
        let saveArchivedTurns = saveSlot.get("archivedTurns") as
          | Y.Array<unknown>
          | undefined;
        if (!saveArchivedTurns) {
          saveArchivedTurns = new Y.Array<unknown>();
          saveSlot.set("archivedTurns", saveArchivedTurns);
        }

        // 构建归档数据（包含玩家显示名）
        const actionsWithDisplayName: Record<
          string,
          {
            userId: string;
            content: string;
            submittedAt: number;
            displayName?: string;
          }
        > = {};
        actions.forEach((action, odUserId) => {
          const member = members.get(odUserId);
          actionsWithDisplayName[odUserId] = {
            userId: odUserId,
            content: action.content,
            submittedAt: action.submittedAt,
            displayName: member?.displayName,
          };
        });

        saveArchivedTurns.push([
          {
            turnNumber,
            completedAt: now,
            actions: actionsWithDisplayName,
            aiResponseLength: resolvedAiResponse.length,
            stateChanges: resolvedStateChanges,
          },
        ]);

        // 4. 更新存档时间戳
        saveSlot.set("updatedAt", now);
      }
    }

    // 发布回合完成事件
    const event: TurnCompletedEvent = {
      roomId,
      turnNumber,
      aiResponse: resolvedAiResponse,
      completedAt: now,
      stateChanges: resolvedStateChanges,
    };
    eventBus.emit(eventBus.createEvent(RoomEvents.TURN_COMPLETED, event));

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

// ===== 角色管理 =====

import type {
  CreateCharacterPayload,
  UpdateCharacterPayload,
} from "@/domain/commands/room";
import {
  canOperateCharacter,
  createCharacter,
  type Character,
} from "@/domain/entities/character";
import type {
  CharacterCreatedEvent,
  CharacterUpdatedEvent,
} from "@/domain/events/room";

/**
 * 创建角色命令处理器
 *
 * 流程：
 * 1. 验证房间存在
 * 2. 检查用户是否已有角色（可选：一个用户只能有一个角色）
 * 3. 创建角色实体
 * 4. 写入 MainDoc.characters（使用嵌套 Y.Map）
 * 5. 发布 CHARACTER_CREATED 事件
 */
export async function createCharacterHandler(
  payload: CreateCharacterPayload,
  _context: CommandContext
): Promise<CommandResult<{ characterId: string }>> {
  try {
    const { roomId, name, userId, uniqueTag, attributes } = payload;

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    // 获取 characters Map
    const charactersMap = mainDoc.getMap("characters") as Y.Map<Y.Map<unknown>>;

    // 检查用户是否已有角色（通过 operatorUserId 或 operatorUniqueTag 匹配）
    let existingCharacterId: string | null = null;
    charactersMap.forEach((charMap, charId) => {
      const operatorUserId = charMap.get("operatorUserId") as string;
      const operatorUniqueTag = charMap.get("operatorUniqueTag") as string;
      if (operatorUserId === userId || operatorUniqueTag === uniqueTag) {
        existingCharacterId = charId;
      }
    });

    if (existingCharacterId) {
      return {
        success: false,
        error: `用户已有角色，请使用更新命令修改角色信息`,
      };
    }

    // 创建角色实体
    const character = createCharacter({
      name,
      creatorUniqueTag: uniqueTag,
      operatorUserId: userId,
      operatorUniqueTag: uniqueTag,
      status: "active",
      attributes,
    });

    // 写入 MainDoc.characters（使用嵌套 Y.Map 支持增量同步）
    mainDoc.transact(() => {
      const charMap = new Y.Map<unknown>();
      charMap.set("id", character.id);
      charMap.set("name", character.name);
      charMap.set("creatorUniqueTag", character.creatorUniqueTag);
      charMap.set("operatorUserId", character.operatorUserId);
      charMap.set("operatorUniqueTag", character.operatorUniqueTag);
      charMap.set("status", character.status);
      charMap.set("createdAt", character.createdAt);
      charMap.set("updatedAt", character.updatedAt);
      if (character.attributes) {
        charMap.set("attributes", character.attributes);
      }
      charactersMap.set(character.id, charMap);
    });

    // 发布 CHARACTER_CREATED 事件
    const event: CharacterCreatedEvent = {
      roomId,
      characterId: character.id,
      name: character.name,
      creatorUniqueTag: character.creatorUniqueTag,
      operatorUserId: character.operatorUserId,
      operatorUniqueTag: character.operatorUniqueTag,
      status: character.status,
      createdAt: character.createdAt,
    };
    eventBus.emit(eventBus.createEvent(RoomEvents.CHARACTER_CREATED, event));

    return { success: true, data: { characterId: character.id } };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * 更新角色命令处理器
 *
 * 流程：
 * 1. 验证房间和角色存在
 * 2. 验证操作权限（userId 或 uniqueTag 匹配）
 * 3. 更新角色属性
 * 4. 发布 CHARACTER_UPDATED 事件
 */
export async function updateCharacterHandler(
  payload: UpdateCharacterPayload,
  _context: CommandContext
): Promise<CommandResult<void>> {
  try {
    const { roomId, characterId, userId, uniqueTag, updates } = payload;
    const now = Date.now();

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return { success: false, error: `MainDoc not found: ${roomId}` };
    }

    // 获取 characters Map
    const charactersMap = mainDoc.getMap("characters") as Y.Map<Y.Map<unknown>>;

    // 获取角色
    const charMap = charactersMap.get(characterId);
    if (!charMap) {
      return { success: false, error: `角色不存在: ${characterId}` };
    }

    // 构建角色对象用于权限检查
    const character: Character = {
      id: charMap.get("id") as string,
      name: charMap.get("name") as string,
      creatorUniqueTag: charMap.get("creatorUniqueTag") as string,
      operatorUserId: charMap.get("operatorUserId") as string,
      operatorUniqueTag: charMap.get("operatorUniqueTag") as string,
      status: charMap.get("status") as Character["status"],
      createdAt: charMap.get("createdAt") as number,
      updatedAt: charMap.get("updatedAt") as number,
      attributes: charMap.get("attributes") as
        | Record<string, unknown>
        | undefined,
    };

    // 验证操作权限
    if (!canOperateCharacter(character, userId, uniqueTag)) {
      return { success: false, error: "无权操作此角色" };
    }

    // 更新角色属性（使用 transact 确保原子性）
    mainDoc.transact(() => {
      if (updates.name !== undefined) {
        charMap.set("name", updates.name);
      }
      if (updates.status !== undefined) {
        charMap.set("status", updates.status);
      }
      if (updates.attributes !== undefined) {
        // 合并属性而非替换
        const existingAttrs =
          (charMap.get("attributes") as Record<string, unknown>) || {};
        charMap.set("attributes", { ...existingAttrs, ...updates.attributes });
      }
      charMap.set("updatedAt", now);
    });

    // 发布 CHARACTER_UPDATED 事件
    const event: CharacterUpdatedEvent = {
      roomId,
      characterId,
      operatorUserId: userId,
      operatorUniqueTag: uniqueTag,
      updates,
      updatedAt: now,
    };
    eventBus.emit(eventBus.createEvent(RoomEvents.CHARACTER_UPDATED, event));

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * 查询房间 Hook
 *
 * 通过 CommandBus 查询房间信息（用于加入前预览）
 * ✅ 符合架构规范：通过 CommandBus 发送命令
 */

import { RoomCommands, type QueryRoomResult } from "@/domain/commands/room";
import { useCommand } from "@/hooks";
import { useCallback, useState } from "react";

/**
 * 房间预览信息
 */
export interface RoomPreview {
  /** 房间 ID */
  roomId: string;
  /** 房间名称 */
  name: string;
  /** 房主显示名称 */
  hostName: string;
  /** 当前成员数 */
  memberCount: number;
  /** 最大玩家数 */
  maxPlayers: number;
}

/**
 * 查询房间 Hook
 *
 * 用于加入房间前预览房间信息
 *
 * @returns 房间预览、查询状态、错误信息、查询函数、重置函数
 *
 * @example
 * ```tsx
 * const { roomPreview, isQuerying, queryError, query, reset } = useQueryRoom();
 *
 * // 输入房间码后自动查询
 * const handleCodeChange = (code: string) => {
 *   if (code.length === 6) {
 *     query(code);
 *   } else {
 *     reset();
 *   }
 * };
 *
 * // 显示房间预览
 * {roomPreview && (
 *   <div>
 *     <p>房间名: {roomPreview.name}</p>
 *     <p>房主: {roomPreview.hostName}</p>
 *     <p>人数: {roomPreview.memberCount}/{roomPreview.maxPlayers}</p>
 *   </div>
 * )}
 * ```
 */
export function useQueryRoom() {
  const dispatch = useCommand();
  const [roomPreview, setRoomPreview] = useState<RoomPreview | null>(null);
  const [isQuerying, setIsQuerying] = useState(false);
  const [queryError, setQueryError] = useState<string | null>(null);

  const query = useCallback(
    async (code: string) => {
      setIsQuerying(true);
      setQueryError(null);
      setRoomPreview(null);

      try {
        const result = await dispatch({
          type: RoomCommands.QUERY_ROOM,
          payload: { code },
        });

        if (result.success) {
          const data = result.data as QueryRoomResult;
          setRoomPreview({
            roomId: data.roomId,
            name: data.name,
            hostName: data.hostName,
            memberCount: data.memberCount,
            maxPlayers: data.maxPlayers,
          });
          return { success: true, data };
        } else {
          const errorMsg = result.error || "房间不存在或已过期";
          setQueryError(errorMsg);
          return { success: false, error: errorMsg };
        }
      } catch (_e) {
        const errorMsg = "查询失败，请检查网络";
        setQueryError(errorMsg);
        return { success: false, error: errorMsg };
      } finally {
        setIsQuerying(false);
      }
    },
    [dispatch]
  );

  const reset = useCallback(() => {
    setRoomPreview(null);
    setQueryError(null);
  }, []);

  return { roomPreview, isQuerying, queryError, query, reset };
}

/**
 * 房间角色 Hook
 *
 * 获取房间角色列表和当前用户的角色信息
 * ✅ 符合架构规范：UI 组件只读取状态
 */

import { subdocManager } from "@/core/yjs";
import type { Character } from "@/domain/entities/character";
import { canOperateCharacter } from "@/domain/entities/character";
import { getOrCreateUserId, getUniqueTag } from "@/lib/user-identity";
import { useCallback, useEffect, useMemo, useState } from "react";
import * as Y from "yjs";
import { useRoomStore } from "../store";

/**
 * 从 Y.Map 提取 Character 对象
 */
function extractCharacterFromYMap(charMap: Y.Map<unknown>): Character {
  return {
    id: charMap.get("id") as string,
    name: charMap.get("name") as string,
    creatorUniqueTag: charMap.get("creatorUniqueTag") as string,
    operatorUserId: charMap.get("operatorUserId") as string,
    operatorUniqueTag: charMap.get("operatorUniqueTag") as string,
    status: charMap.get("status") as Character["status"],
    createdAt: charMap.get("createdAt") as number,
    updatedAt: charMap.get("updatedAt") as number,
    attributes: charMap.get("attributes") as
      | Record<string, unknown>
      | undefined,
  };
}

/**
 * 角色列表 Hook 返回值
 */
export interface UseRoomCharactersResult {
  /** 所有角色列表 */
  characters: Character[];
  /** 当前用户的角色（如果有） */
  myCharacter: Character | null;
  /** 当前用户是否已有角色 */
  hasCharacter: boolean;
  /** 刷新角色列表 */
  refresh: () => void;
}

/**
 * 获取房间角色列表
 *
 * @returns 角色列表和当前用户角色信息
 *
 * @example
 * ```tsx
 * const { characters, myCharacter, hasCharacter } = useRoomCharacters();
 *
 * return (
 *   <div>
 *     {hasCharacter ? (
 *       <p>你的角色: {myCharacter?.name}</p>
 *     ) : (
 *       <CharacterCreationForm />
 *     )}
 *   </div>
 * );
 * ```
 */
export function useRoomCharacters(): UseRoomCharactersResult {
  const currentRoom = useRoomStore((s) => s.currentRoom);
  const [characters, setCharacters] = useState<Character[]>([]);

  const userId = useMemo(() => getOrCreateUserId(), []);
  const uniqueTag = useMemo(() => getUniqueTag() || "", []);

  // 刷新角色列表
  const refresh = useCallback(() => {
    if (!currentRoom) {
      setCharacters([]);
      return;
    }

    const mainDoc = subdocManager.getMainDoc(currentRoom.roomId);
    if (!mainDoc) {
      setCharacters([]);
      return;
    }

    const charactersMap = mainDoc.getMap("characters") as Y.Map<Y.Map<unknown>>;
    const charList: Character[] = [];

    charactersMap.forEach((charMap) => {
      try {
        const character = extractCharacterFromYMap(charMap);
        charList.push(character);
      } catch (_error) {
        // 角色提取失败，跳过
      }
    });

    setCharacters(charList);
  }, [currentRoom]);

  // 监听角色变化
  useEffect(() => {
    if (!currentRoom) {
      setCharacters([]);
      return;
    }

    const mainDoc = subdocManager.getMainDoc(currentRoom.roomId);
    if (!mainDoc) {
      return;
    }

    const charactersMap = mainDoc.getMap("characters") as Y.Map<Y.Map<unknown>>;

    // 初始加载
    refresh();

    // 监听变化
    const observer = () => {
      refresh();
    };

    charactersMap.observeDeep(observer);

    return () => {
      charactersMap.unobserveDeep(observer);
    };
  }, [currentRoom, refresh]);

  // 计算当前用户的角色
  const myCharacter = useMemo(() => {
    return (
      characters.find((char) => canOperateCharacter(char, userId, uniqueTag)) ||
      null
    );
  }, [characters, userId, uniqueTag]);

  const hasCharacter = myCharacter !== null;

  return {
    characters,
    myCharacter,
    hasCharacter,
    refresh,
  };
}

/**
 * 回合消息 Hook
 *
 * 用于联机模式下展示回合消息
 * 结合 HistoryDoc 的归档消息和当前 TurnDoc 的实时数据
 *
 * ⚠️ 架构说明：
 * 使用 useTurnDocStatus 监听 TurnDoc 的同步状态，
 * 确保只有在 TurnDoc 同步完成后才设置观察器。
 */

import { subdocManager, yjsManager } from "@/core/yjs";
import type { Member, PlayerAction } from "@/core/yjs/room/types";
import type { Character } from "@/domain/entities/character";
import type { Message } from "@/domain/entities/message";
import { useCallback, useEffect, useState } from "react";
import * as Y from "yjs";
import {
  convertTurnToMessages,
  toMessageEntities,
} from "../services/turn-converter";
import { useRoomStore } from "../store";
import { useTurnDocStatus } from "./useTurnDocStatus";

/**
 * 回合消息状态
 */
export interface TurnMessagesState {
  /** 消息列表 */
  messages: Message[];
  /** 是否正在加载 */
  loading: boolean;
  /** 错误信息 */
  error: Error | null;
  /** 当前回合号 */
  currentTurn: number;
  /** AI 响应是否正在流式输出 */
  isStreaming: boolean;
}

/**
 * 回合消息 Hook 返回值
 */
export interface UseTurnMessagesReturn extends TurnMessagesState {
  /** 刷新消息 */
  refresh: () => void;
}

/**
 * 回合消息 Hook
 *
 * 特性：
 * 1. 从 HistoryDoc 加载历史消息（已完成回合）
 * 2. 从当前 TurnDoc 实时获取进行中的行动和 AI 响应
 * 3. 自动合并历史和实时消息
 * 4. 响应式更新
 *
 * @param roomId 房间 ID
 */
export function useTurnMessages(roomId: string | null): UseTurnMessagesReturn {
  const [messages, setMessages] = useState<Message[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [currentTurn, setCurrentTurn] = useState(0);
  const [isStreaming, setIsStreaming] = useState(false);

  // 从 MainDoc 获取的当前回合号（用于 useTurnDocStatus）
  const [turnFromMain, setTurnFromMain] = useState(0);

  // 监听 MainDoc 连接状态
  const connectionStatus = useRoomStore((s) => s.connectionStatus);

  // 监听 TurnDoc 的同步状态
  const turnDocStatus = useTurnDocStatus(roomId, turnFromMain);

  // 会话 ID
  const conversationId = roomId ? `room:${roomId}:main` : null;

  /**
   * 从 SaveSlot 加载持久化的历史消息
   */
  const loadSaveSlotMessages = useCallback((): Message[] => {
    if (!conversationId) {
      return [];
    }

    try {
      const currentSaveId = yjsManager.getCurrentSaveId();
      if (!currentSaveId) {
        return [];
      }

      const saveSlot = yjsManager.getSaveSlots().get(currentSaveId) as
        | Y.Map<unknown>
        | undefined;
      if (!saveSlot) {
        return [];
      }

      const messagesMap = saveSlot.get("messages") as
        | Y.Map<Y.Array<unknown>>
        | undefined;
      if (!messagesMap) {
        return [];
      }

      const messagesArray = messagesMap.get(conversationId);
      if (!messagesArray) {
        return [];
      }

      const messages = messagesArray.toArray() as Message[];
      return messages;
    } catch (_err) {
      return [];
    }
  }, [conversationId]);

  /**
   * 从 HistoryDoc 加载实时消息（本次游戏新产生）
   */
  const loadHistoryDocMessages = useCallback(async (): Promise<Message[]> => {
    if (!roomId || !conversationId) {
      return [];
    }

    try {
      const historyDoc = await subdocManager.loadHistoryDoc(roomId);
      const messagesMap = historyDoc.getMap("messages") as Y.Map<
        Y.Array<unknown>
      >;
      const messagesArray = messagesMap.get(conversationId);

      if (!messagesArray) {
        return [];
      }

      return messagesArray.toArray() as Message[];
    } catch (_err) {
      return [];
    }
  }, [roomId, conversationId]);

  /**
   * 合并 SaveSlot 和 HistoryDoc 消息（去重）
   * SaveSlot 包含持久化的历史消息
   * HistoryDoc 包含本次游戏新产生的实时消息
   */
  const loadHistoryMessages = useCallback(async (): Promise<Message[]> => {
    // 1. 从 SaveSlot 加载持久化消息
    const saveSlotMessages = loadSaveSlotMessages();

    // 2. 从 HistoryDoc 加载实时消息
    const historyDocMessages = await loadHistoryDocMessages();

    // 3. 合并并去重（使用消息 ID）
    const messageMap = new Map<string, Message>();

    // 先添加 SaveSlot 消息
    for (const msg of saveSlotMessages) {
      messageMap.set(msg.id, msg);
    }

    // 再添加 HistoryDoc 消息（如果 ID 相同则覆盖，保持最新）
    for (const msg of historyDocMessages) {
      messageMap.set(msg.id, msg);
    }

    // 按创建时间排序
    const mergedMessages = Array.from(messageMap.values()).sort(
      (a, b) => a.createdAt - b.createdAt
    );

    return mergedMessages;
  }, [loadSaveSlotMessages, loadHistoryDocMessages]);

  /**
   * 从当前 TurnDoc 获取进行中的消息
   */
  const getCurrentTurnMessages = useCallback((): Message[] => {
    if (!roomId) {
      return [];
    }

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return [];
    }

    const configMap = mainDoc.getMap("config");
    const turnNumber = (configMap.get("currentTurnNumber") as number) || 0;

    if (turnNumber <= 0) {
      return [];
    }

    const turnDoc = subdocManager.getTurnDoc(roomId, turnNumber);
    if (!turnDoc) {
      return [];
    }

    // 获取成员信息
    const membersMap = mainDoc.getMap("members") as Y.Map<Member>;
    const members = new Map<string, Member>();
    membersMap.forEach((member, id) => {
      members.set(id, member);
    });

    // 获取角色信息（用于显示角色名称而非玩家名称）
    const charactersMap = mainDoc.getMap("characters") as Y.Map<Y.Map<unknown>>;
    const characters: Character[] = [];
    charactersMap.forEach((charMap) => {
      try {
        const character: Character = {
          id: charMap.get("id") as string,
          name: charMap.get("name") as string,
          creatorUniqueTag: charMap.get("creatorUniqueTag") as string,
          operatorUserId: charMap.get("operatorUserId") as string,
          operatorUniqueTag: charMap.get("operatorUniqueTag") as string,
          status: charMap.get("status") as Character["status"],
          createdAt: charMap.get("createdAt") as number,
          updatedAt: charMap.get("updatedAt") as number,
          attributes: charMap.get("attributes") as
            | Record<string, unknown>
            | undefined,
        };
        characters.push(character);
      } catch (_err) {
        // 角色提取失败，跳过
      }
    });

    // 获取玩家行动
    const actionsMap = turnDoc.getMap("actions") as Y.Map<PlayerAction>;
    const actions = new Map<string, PlayerAction>();
    actionsMap.forEach((action, userId) => {
      actions.set(userId, action);
    });

    // 获取 AI 响应
    const aiResponseText = turnDoc.getText("aiResponse");
    const aiResponse = aiResponseText.toString();

    // 检查回合状态
    const turnConfig = turnDoc.getMap("config");
    const status = turnConfig.get("status") as string;

    // 如果回合已完成，不需要这里生成消息（由 HistoryDoc 提供）
    if (status === "completed") {
      return [];
    }

    // 如果没有行动且没有 AI 响应，不生成消息
    if (actions.size === 0 && !aiResponse) {
      return [];
    }

    // 生成当前回合的消息（传入角色信息以显示角色名称）
    const result = convertTurnToMessages({
      turnNumber,
      actions,
      members,
      characters,
      aiResponse: aiResponse || "", // 可能为空（正在等待 AI 响应）
      completedAt: Date.now(),
      conversationId: conversationId!,
    });

    // 如果 AI 正在流式输出，标记最后一条消息为 streaming
    const messageEntities = toMessageEntities(result.messages, conversationId!);

    if (aiResponse && status === "processing") {
      setIsStreaming(true);
      // 标记 AI 消息为 streaming 状态
      const lastMsg = messageEntities[messageEntities.length - 1];
      if (lastMsg && lastMsg.role === "assistant") {
        lastMsg.status = "streaming";
      }
    } else {
      setIsStreaming(false);
    }

    return messageEntities;
  }, [roomId, conversationId]);

  /**
   * 刷新消息
   */
  const refresh = useCallback(async () => {
    if (!roomId) {
      setMessages([]);
      setCurrentTurn(0);
      return;
    }

    setLoading(true);
    setError(null);

    try {
      // 加载历史消息
      const historyMessages = await loadHistoryMessages();

      // 获取当前回合消息
      const currentMessages = getCurrentTurnMessages();

      // 合并消息
      const mergedMessages = [...historyMessages, ...currentMessages];
      setMessages(mergedMessages);

      // 更新当前回合号
      const mainDoc = subdocManager.getMainDoc(roomId);
      if (mainDoc) {
        const configMap = mainDoc.getMap("config");
        const turnNumber = (configMap.get("currentTurnNumber") as number) || 0;
        setCurrentTurn(turnNumber);
      }
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
    } finally {
      setLoading(false);
    }
  }, [roomId, loadHistoryMessages, getCurrentTurnMessages]);

  // Effect 1: MainDoc 同步后，监听当前回合号变化
  useEffect(() => {
    if (!roomId || connectionStatus !== "synced") {
      setTurnFromMain(0);
      return;
    }

    const mainDoc = subdocManager.getMainDoc(roomId);
    if (!mainDoc) {
      return;
    }

    const configMap = mainDoc.getMap("config");

    // 更新回合号并刷新
    const updateTurnNumber = () => {
      const turn = (configMap.get("currentTurnNumber") as number) || 0;
      setTurnFromMain(turn);
      setCurrentTurn(turn);
      // 回合号变化时触发刷新
      refresh();
    };

    // 初始化
    updateTurnNumber();

    // 监听配置变化（回合号变化）
    configMap.observe(updateTurnNumber);

    return () => {
      configMap.unobserve(updateTurnNumber);
    };
  }, [roomId, connectionStatus, refresh]);

  // Effect 2: TurnDoc 同步后，设置 TurnDoc 观察器
  useEffect(() => {
    // 只有当 TurnDoc 已同步才设置观察器
    if (!roomId || turnFromMain <= 0 || turnDocStatus !== "synced") {
      return;
    }

    // TurnDoc 同步完成，刷新一次
    refresh();

    // 设置 TurnDoc 观察器
    const turnDoc = subdocManager.getTurnDoc(roomId, turnFromMain);
    if (!turnDoc) {
      return;
    }

    const actionsMap = turnDoc.getMap("actions");
    const aiResponseText = turnDoc.getText("aiResponse");

    const observer = () => refresh();

    actionsMap.observe(observer);
    aiResponseText.observe(observer);

    return () => {
      actionsMap.unobserve(observer);
      aiResponseText.unobserve(observer);
    };
  }, [roomId, turnFromMain, turnDocStatus, refresh]);

  // Effect 3: roomId 变化时重置状态
  useEffect(() => {
    if (!roomId) {
      setMessages([]);
      setCurrentTurn(0);
      setTurnFromMain(0);
    }
  }, [roomId]);

  return {
    messages,
    loading,
    error,
    currentTurn,
    isStreaming,
    refresh,
  };
}

/**
 * 房间模块
 *
 * 负责联机房间的创建、加入、回合管理等功能
 *
 * ⚠️ 架构说明：
 * - 命令处理器负责业务逻辑和状态修改
 * - 事件订阅负责更新 Store（事件驱动）
 * - UI 组件只读取 Store，不直接调用修改方法
 * - Yjs 文档变化通过 RoomSyncBridge 同步到 Store 并派生事件
 */

import { commandBus } from "@/core/command-bus";
import { eventBus } from "@/core/event-bus";
import { multiplayerProvider, subdocManager } from "@/core/yjs";
import type { Member } from "@/core/yjs/room/types";
import { RoomCommands } from "@/domain/commands/room";
import {
  RoomEvents,
  type MemberJoinedEvent,
  type MemberLeftEvent,
  type RoomCreatedEvent,
} from "@/domain/events/room";
import { SaveEvents, type SaveLoadedPayload } from "@/domain/events/save";
import type * as Y from "yjs";
import {
  cancelAiTurnHandler,
  processAiTurnHandler,
  regenerateAiTurnHandler,
} from "./commands/ai-handlers";
import {
  advancePhaseHandler,
  completePhaseHandler,
  completeTurnHandler,
  createCharacterHandler,
  createRoomHandler,
  endGameHandler,
  enterPhaseHandler,
  extendTurnDeadlineHandler,
  forceStartTurnHandler,
  joinRoomHandler,
  leaveRoomHandler,
  lockActionHandler,
  queryRoomHandler,
  startGameHandler,
  startTurnHandler,
  submitActionHandler,
  transferHostHandler,
  updateCharacterHandler,
  updateMemberStatusHandler,
} from "./commands/handlers";
import { useRoomStore } from "./store";
import { RoomSyncBridge } from "./sync";

// 房间解散处理标记，避免重复处理
let disbandedHandled = false;

// ===== 事件订阅取消函数 =====
let unsubscribers: Array<() => void> = [];

// ===== Yjs 观察器取消函数 =====
let yjsObserverCleanup: (() => void) | null = null;

// ===== RoomSyncBridge 实例 =====
let roomSyncBridge: RoomSyncBridge | null = null;

/**
 * 设置 RoomSyncBridge
 *
 * 在房间连接同步完成后调用，负责：
 * 1. 监听 Yjs 状态变化
 * 2. 派生领域事件（GAME_STARTED, MEMBER_JOINED 等）
 * 3. 同步状态到 Store
 */
function setupRoomSyncBridge(roomId: string): void {
  // 清理旧的 SyncBridge
  if (roomSyncBridge) {
    roomSyncBridge.destroy();
    roomSyncBridge = null;
  }

  // 创建新的 SyncBridge
  roomSyncBridge = new RoomSyncBridge(roomId);
  roomSyncBridge.setup();
}

/**
 * 清理 RoomSyncBridge
 */
function cleanupRoomSyncBridge(): void {
  if (roomSyncBridge) {
    roomSyncBridge.destroy();
    roomSyncBridge = null;
  }
}

/**
 * 设置事件订阅
 *
 * 订阅房间相关事件，自动更新 Store 状态
 */
function setupEventSubscriptions(): void {
  const store = useRoomStore.getState();

  // 房间创建事件
  unsubscribers.push(
    eventBus.on(RoomEvents.ROOM_CREATED, (event) => {
      const payload = event.payload as RoomCreatedEvent;
      store.setCurrentRoom({
        roomId: payload.roomId,
        code: payload.code,
        name: payload.name,
        isHost: true,
        maxPlayers: payload.maxPlayers,
        turnDuration: payload.turnDuration,
      });
      store.setMode("online");
      store.setLoading(false);
    })
  );

  // 成员加入事件
  unsubscribers.push(
    eventBus.on(RoomEvents.MEMBER_JOINED, (event) => {
      const payload = event.payload as MemberJoinedEvent;
      const currentRoom = useRoomStore.getState().currentRoom;

      // 如果是当前用户加入（非房主），更新房间信息
      const localUser = useRoomStore.getState().localUser;
      if (payload.userId === localUser.userId && !currentRoom) {
        store.setCurrentRoom({
          roomId: payload.roomId,
          code: "", // 需要从其他地方获取
          name: "", // 需要从其他地方获取
          isHost: payload.role === "host",
          maxPlayers: 8,
          turnDuration: 5 * 60 * 1000,
        });
        store.setMode("online");
      }

      // 添加成员到列表
      store.addMember({
        userId: payload.userId,
        displayName: payload.displayName,
        role: payload.role,
        joinedAt: payload.joinedAt,
        lastActiveAt: Date.now(),
        status: "online",
      });
      store.setLoading(false);
    })
  );

  // 成员离开事件
  unsubscribers.push(
    eventBus.on(RoomEvents.MEMBER_LEFT, (event) => {
      const payload = event.payload as MemberLeftEvent;
      const localUser = useRoomStore.getState().localUser;

      // 如果是当前用户离开，重置状态
      if (payload.userId === localUser.userId) {
        store.reset();
      } else {
        // 更新成员状态
        store.updateMemberStatus(payload.userId, "offline");
      }
    })
  );

  // 连接事件
  unsubscribers.push(
    eventBus.on(RoomEvents.CONNECTED, () => {
      store.setConnectionStatus("connected");
    })
  );

  // 断开连接事件
  unsubscribers.push(
    eventBus.on(RoomEvents.DISCONNECTED, () => {
      store.setConnectionStatus("disconnected");
    })
  );

  // 重连中事件
  unsubscribers.push(
    eventBus.on(RoomEvents.RECONNECTING, () => {
      store.setConnectionStatus("reconnecting");
    })
  );

  // 存档加载事件 - 当加载单人存档时重置房间状态
  unsubscribers.push(
    eventBus.on(SaveEvents.SAVE_LOADED, (event) => {
      const payload = event.payload as SaveLoadedPayload;

      // 只有加载单人存档时才重置房间状态
      if (payload.saveType === "solo") {
        store.reset();
      }
    })
  );

  // 重连成功事件
  unsubscribers.push(
    eventBus.on(RoomEvents.RECONNECTED, () => {
      store.setConnectionStatus("synced");
    })
  );

  // 成员状态更新事件
  unsubscribers.push(
    eventBus.on(RoomEvents.MEMBER_STATUS_UPDATED, (event) => {
      const payload = event.payload as {
        roomId: string;
        userId: string;
        status: "online" | "away" | "offline";
      };
      store.updateMemberStatus(payload.userId, payload.status);
    })
  );

  // 房主转让事件
  unsubscribers.push(
    eventBus.on(RoomEvents.HOST_TRANSFERRED, (event) => {
      const payload = event.payload as {
        roomId: string;
        previousHostId: string;
        newHostId: string;
      };
      const localUser = useRoomStore.getState().localUser;
      const currentRoom = useRoomStore.getState().currentRoom;

      if (currentRoom) {
        // 更新当前用户是否为房主
        store.setCurrentRoom({
          ...currentRoom,
          isHost: payload.newHostId === localUser.userId,
        });
      }

      // 更新成员角色
      const members = useRoomStore.getState().members;
      const updatedMembers = members.map((m) => {
        if (m.userId === payload.previousHostId) {
          return { ...m, role: "guest" as const };
        }
        if (m.userId === payload.newHostId) {
          return { ...m, role: "host" as const };
        }
        return m;
      });
      store.setMembers(updatedMembers);
    })
  );
}

/**
 * 设置 Yjs 成员列表观察器
 *
 * 监听 MainDoc 中 members Map 的变化，自动同步到 Store
 * 这是实现多客户端成员列表同步的关键
 *
 * 同时监听 disbanded 标记，当房主解散房间时自动通知成员
 */
function setupYjsMembersObserver(roomId: string): () => void {
  const mainDoc = subdocManager.getMainDoc(roomId);
  if (!mainDoc) {
    console.warn("[RoomModule] Cannot setup observer: MainDoc not found");
    return () => {};
  }

  const membersMap = mainDoc.getMap("members") as Y.Map<Member>;
  const metadataMap = mainDoc.getMap("metadata");
  const configMap = mainDoc.getMap("config");
  const store = useRoomStore.getState();

  // 重置处理标记
  disbandedHandled = false;

  // 同步当前成员列表到 Store
  const syncMembersToStore = () => {
    const members: Member[] = [];
    membersMap.forEach((member) => {
      members.push(member);
    });
    // 按加入时间排序
    members.sort((a, b) => a.joinedAt - b.joinedAt);
    store.setMembers(members);
  };

  // 同步房间元数据到 Store（包括 maxPlayers）
  // 同时检测 disbanded 标记和游戏开始状态
  const syncMetadataToStore = () => {
    const currentRoom = store.currentRoom;
    const localUser = store.localUser;
    const hostUserId = metadataMap.get("hostUserId") as string | undefined;

    // 检测房间是否被解散
    const disbanded = metadataMap.get("disbanded") as boolean | undefined;
    if (disbanded && !disbandedHandled) {
      disbandedHandled = true;

      // 只有非房主才需要处理解散通知
      if (localUser.userId && hostUserId !== localUser.userId) {
        // 发布房间解散事件
        eventBus.emit(
          eventBus.createEvent(RoomEvents.ROOM_DELETED, {
            roomId,
            deletedAt: Date.now(),
            reason: "disbanded",
          })
        );

        // 自动离开房间（通过 commandBus 触发）
        commandBus.dispatch({
          type: RoomCommands.LEAVE_ROOM,
          payload: { roomId, userId: localUser.userId },
        });

        return; // 不再继续同步，因为即将离开
      }
    }

    // ⚠️ SyncBridge 改造：移除 GAME_STARTED 事件的手动 emit
    // 现在由 SyncBridge 通过检测 status: waiting → playing 自动派生

    if (currentRoom) {
      const maxPlayers = (metadataMap.get("maxPlayers") as number) || 8;
      const turnDuration =
        (metadataMap.get("turnDuration") as number) || 5 * 60 * 1000;
      const name = (metadataMap.get("name") as string) || currentRoom.name;
      const code = (metadataMap.get("code") as string) || currentRoom.code;

      // 只有当值变化时才更新
      if (
        currentRoom.maxPlayers !== maxPlayers ||
        currentRoom.turnDuration !== turnDuration ||
        currentRoom.name !== name ||
        currentRoom.code !== code
      ) {
        store.setCurrentRoom({
          ...currentRoom,
          maxPlayers,
          turnDuration,
          name,
          code,
        });
      }
    }
  };

  // 初始同步
  syncMembersToStore();
  syncMetadataToStore();

  // 观察 members Map 变化
  const membersObserver = () => {
    syncMembersToStore();
  };
  membersMap.observe(membersObserver);

  // 观察 metadata Map 变化（包括 disbanded 标记和 status）
  const metadataObserver = () => {
    syncMetadataToStore();
  };
  metadataMap.observe(metadataObserver);

  // 观察 config Map 变化（包括 currentTurnNumber）
  const configObserver = () => {
    syncMetadataToStore();
  };
  configMap.observe(configObserver);

  // 返回清理函数
  return () => {
    membersMap.unobserve(membersObserver);
    metadataMap.unobserve(metadataObserver);
    configMap.unobserve(configObserver);
    disbandedHandled = false;
  };
}

/**
 * 设置 MultiplayerProvider 事件监听
 *
 * 将 Provider 的连接状态变化转发为事件
 */
function setupProviderListeners(): void {
  // 监听连接状态变化
  multiplayerProvider.on("onStatusChange", (status) => {
    const store = useRoomStore.getState();
    store.setConnectionStatus(status);

    // 根据状态发布对应事件
    const config = multiplayerProvider.getConfig();
    if (config) {
      const eventPayload = {
        roomId: config.roomId,
        userId: config.userId,
        timestamp: Date.now(),
      };

      switch (status) {
        case "connected":
          eventBus.emit(
            eventBus.createEvent(RoomEvents.CONNECTED, eventPayload)
          );
          break;
        case "synced":
          // 同步完成后，设置 Yjs 观察器和 SyncBridge
          if (yjsObserverCleanup) {
            yjsObserverCleanup();
          }
          yjsObserverCleanup = setupYjsMembersObserver(config.roomId);
          // 设置 RoomSyncBridge（派生事件的核心）
          setupRoomSyncBridge(config.roomId);
          eventBus.emit(
            eventBus.createEvent(RoomEvents.RECONNECTED, eventPayload)
          );
          break;
        case "reconnecting":
          // 通知 SyncBridge 重连中
          if (roomSyncBridge) {
            roomSyncBridge.onReconnect();
          }
          eventBus.emit(
            eventBus.createEvent(RoomEvents.RECONNECTING, eventPayload)
          );
          break;
        case "disconnected":
          // 清理 Yjs 观察器和 SyncBridge
          if (yjsObserverCleanup) {
            yjsObserverCleanup();
            yjsObserverCleanup = null;
          }
          cleanupRoomSyncBridge();
          eventBus.emit(
            eventBus.createEvent(RoomEvents.DISCONNECTED, eventPayload)
          );
          break;
        case "error":
          store.setError("连接错误");
          break;
      }
    }
  });

  // 监听同步完成
  multiplayerProvider.on("onSynced", () => {
    const store = useRoomStore.getState();
    store.setConnectionStatus("synced");

    // 同步完成后，设置 Yjs 观察器和 SyncBridge（确保覆盖首次同步的情况）
    const config = multiplayerProvider.getConfig();
    if (config) {
      if (yjsObserverCleanup) {
        yjsObserverCleanup();
      }
      yjsObserverCleanup = setupYjsMembersObserver(config.roomId);
      // 设置 RoomSyncBridge（派生事件的核心）
      setupRoomSyncBridge(config.roomId);
    }
  });

  // 监听错误
  multiplayerProvider.on("onError", (error) => {
    const store = useRoomStore.getState();
    store.setError(error.message);
    store.setConnectionStatus("error");
  });
}

